-- 仅用于绑定时核对业务源行，禁止在最终绘制时反查。
return {
	["game.equipment_flavour.fouruniqueamulet1.text_1"] = "A hearth unyielding, ever warm,",
	["game.equipment_flavour.fouruniqueamulet1.text_2"] = "A light unbroken, endlessly reborn.",
	["game.equipment_flavour.fouruniqueamulet10.text_1"] = "Healing the soul requires sacrifice.",
	["game.equipment_flavour.fouruniqueamulet12.text_1"] = "Fanatics are the most dangerous enemy,",
	["game.equipment_flavour.fouruniqueamulet12.text_2"] = "for they care not for their own survival.",
	["game.equipment_flavour.fouruniqueamulet13.text_1"] = "Forge your Perseverance on the Anvil of Faith.",
	["game.equipment_flavour.fouruniqueamulet14.text_1"] = "Let the unrepentant be dragged ever downwards by the weight of their sins.",
	["game.equipment_flavour.fouruniqueamulet15.text_1"] = "Mindless rage will shake the world,",
	["game.equipment_flavour.fouruniqueamulet15.text_2"] = "Cunning lies will bend it.",
	["game.equipment_flavour.fouruniqueamulet15.text_3"] = "Reckless haste will break the world,",
	["game.equipment_flavour.fouruniqueamulet15.text_4"] = "And into darkness send it.",
	["game.equipment_flavour.fouruniqueamulet16.text_1"] = "He knew not why he was changing, only",
	["game.equipment_flavour.fouruniqueamulet16.text_2"] = "that he wanted to hold his family close...",
	["game.equipment_flavour.fouruniqueamulet17.text_1"] = "The homeguard signalled for aid against a surprise attack,",
	["game.equipment_flavour.fouruniqueamulet17.text_2"] = "but it was not their dekharas that responded.",
	["game.equipment_flavour.fouruniqueamulet17.text_3"] = "It was Solerai herself.",
	["game.equipment_flavour.fouruniqueamulet18.text_1"] = "Tale-women in training drink of a painful desert fruit.",
	["game.equipment_flavour.fouruniqueamulet18.text_2"] = "Fire, they learn, springs from agony.",
	["game.equipment_flavour.fouruniqueamulet19.text_1"] = "Never blinking, always watching.",
	["game.equipment_flavour.fouruniqueamulet2.text_1"] = "Worship of house gods was tolerated",
	["game.equipment_flavour.fouruniqueamulet2.text_2"] = "in Oriath, so long as it remained private.",
	["game.equipment_flavour.fouruniqueamulet20.text_1"] = "When Kabala the Serpent Queen was banished from Keth,",
	["game.equipment_flavour.fouruniqueamulet20.text_2"] = "the Sekhemas took a single hostage as punishment.",
	["game.equipment_flavour.fouruniqueamulet21.text_1"] = "Remember the past, anticipate the future.",
	["game.equipment_flavour.fouruniqueamulet22.text_1"] = "Dannig sculpted the Verisium to evoke the",
	["game.equipment_flavour.fouruniqueamulet22.text_2"] = "night-blooming lotus of Middengard's stygian peaks,",
	["game.equipment_flavour.fouruniqueamulet22.text_3"] = "which grow only where ash meets the snow and stars.",
	["game.equipment_flavour.fouruniqueamulet23.text_1"] = "To stray is to condemn this world to sin.",
	["game.equipment_flavour.fouruniqueamulet3.text_1"] = "What they saw was what they believed, and",
	["game.equipment_flavour.fouruniqueamulet3.text_2"] = "they believed Lunaris had not abandoned them.",
	["game.equipment_flavour.fouruniqueamulet4.text_1"] = "Gentle anger, raging calm.",
	["game.equipment_flavour.fouruniqueamulet5.text_1"] = "The sacred sap flows slowly, but surely.",
	["game.equipment_flavour.fouruniqueamulet6.text_1"] = "Forged from the blood of countless wars,",
	["game.equipment_flavour.fouruniqueamulet6.text_2"] = "its thirst has only begun.",
	["game.equipment_flavour.fouruniqueamulet7.text_1"] = "Natural grace is born, not earned.",
	["game.equipment_flavour.fouruniqueamulet8.text_1"] = "The respect of Karui warriors is hard to earn,",
	["game.equipment_flavour.fouruniqueamulet8.text_2"] = "but lasts a lifetime... and beyond.",
	["game.equipment_flavour.fouruniqueamulet9.text_1"] = "You are slow, foolish and ignorant.",
	["game.equipment_flavour.fouruniqueamulet9.text_2"] = "I am not.",
	["game.equipment_flavour.fouruniquebelt1.text_1"] = "Kaom's strength was rivaled only by",
	["game.equipment_flavour.fouruniquebelt1.text_2"] = "the great Meginord of the north.",
	["game.equipment_flavour.fouruniquebelt10.text_1"] = "Bleeding just means you're still alive.",
	["game.equipment_flavour.fouruniquebelt12.text_1"] = "All creatures have the potential for greatness or unequivocal failure.",
	["game.equipment_flavour.fouruniquebelt13.text_1"] = "Death is your most important duty.",
	["game.equipment_flavour.fouruniquebelt13.text_2"] = "Face it, or curse your bloodline for all eternity.",
	["game.equipment_flavour.fouruniquebelt15.text_1"] = "Trifle not with the trinket mage.",
	["game.equipment_flavour.fouruniquebelt17.text_1"] = "Clever artifice is not always complex.",
	["game.equipment_flavour.fouruniquebelt18.text_1"] = "\"A man's soul rules from a cavern of bone, learns and",
	["game.equipment_flavour.fouruniquebelt18.text_2"] = "judges through flesh-born windows. The heart is meat.",
	["game.equipment_flavour.fouruniquebelt18.text_3"] = "The head is where the Man is.\"",
	["game.equipment_flavour.fouruniquebelt18.text_4"] = "- Lavianga, Advisor to Kaom",
	["game.equipment_flavour.fouruniquebelt19.text_1"] = "A Templar thinks he's righteous for flogging",
	["game.equipment_flavour.fouruniquebelt19.text_2"] = "himself once for every ten lashings he gives.",
	["game.equipment_flavour.fouruniquebelt2.text_1"] = "Adversity is the soil in",
	["game.equipment_flavour.fouruniquebelt2.text_2"] = "which persistence grows.",
	["game.equipment_flavour.fouruniquebelt21.text_1"] = "Bring mystery to life. Again and again.",
	["game.equipment_flavour.fouruniquebelt23.text_1"] = "Kulemak sat triumphant, raising the crown.",
	["game.equipment_flavour.fouruniquebelt23.text_2"] = "Darkness coiled the world in eternal night.",
	["game.equipment_flavour.fouruniquebelt23.text_3"] = "Victory, a mere moment, came crashing down.",
	["game.equipment_flavour.fouruniquebelt23.text_4"] = "No conqueror, no conquered, only searing Light.",
	["game.equipment_flavour.fouruniquebelt24.text_1"] = "Rivers of power coursed through their veins.",
	["game.equipment_flavour.fouruniquebelt24.text_2"] = "Now, that power is yours, for good or ill.",
	["game.equipment_flavour.fouruniquebelt3.text_1"] = "Below all living things,",
	["game.equipment_flavour.fouruniquebelt3.text_2"] = "there exists a flow...",
	["game.equipment_flavour.fouruniquebelt4.text_1"] = "\"The power of rebirth rivals that of immortality.\"",
	["game.equipment_flavour.fouruniquebelt4.text_2"] = "- Icius Perandus, Antiquities Collection, Item {value_1}",
	["game.equipment_flavour.fouruniquebelt5.text_1"] = "Some families have peculiar gifts...",
	["game.equipment_flavour.fouruniquebelt6.text_1"] = "The Brinerot sail without fear of storms.",
	["game.equipment_flavour.fouruniquebelt8.text_1"] = "Vaal bloodpriests were among the earliest intellectuals on record.",
	["game.equipment_flavour.fouruniquebelt8.text_2"] = "It was they who found that a newly freed soul would",
	["game.equipment_flavour.fouruniquebelt8.text_3"] = "desperately cling to any other source of life.",
	["game.equipment_flavour.fouruniquebelt9.text_1"] = "Tempered by the forbidden flame.",
	["game.equipment_flavour.fouruniquebodydex1.text_1"] = "When cornered and desperate, look within for the rage to break loose.",
	["game.equipment_flavour.fouruniquebodydex10.text_1"] = "Shedding away her regal past,",
	["game.equipment_flavour.fouruniquebodydex10.text_2"] = "she forged a new destiny.",
	["game.equipment_flavour.fouruniquebodydex10.text_3"] = "Sacrificing the ephemeral joys of man,",
	["game.equipment_flavour.fouruniquebodydex10.text_4"] = "she embraced the eternal grasp of nature.",
	["game.equipment_flavour.fouruniquebodydex10.text_5"] = "Seizing her one true wish,",
	["game.equipment_flavour.fouruniquebodydex10.text_6"] = "she found peace at last.",
	["game.equipment_flavour.fouruniquebodydex11.text_1"] = "Feed a beast and it will not hunt.",
	["game.equipment_flavour.fouruniquebodydex11.text_2"] = "Protect it and it will not fight.",
	["game.equipment_flavour.fouruniquebodydex11.text_3"] = "Ferocity must be learned, not taught.",
	["game.equipment_flavour.fouruniquebodydex11.text_4"] = "It is suffering that forges the greatest warriors.",
	["game.equipment_flavour.fouruniquebodydex15.text_1"] = "Hyrri loosed a barrage of arrows,",
	["game.equipment_flavour.fouruniquebodydex15.text_2"] = "tipped with a poisoned hatred",
	["game.equipment_flavour.fouruniquebodydex15.text_3"] = "only oppression can ferment.",
	["game.equipment_flavour.fouruniquebodydex16.text_1"] = "\"The boy is a bad omen,\" he cried. \"Ravens gather",
	["game.equipment_flavour.fouruniquebodydex16.text_2"] = "before him!\" That night, a new raven appeared, and",
	["game.equipment_flavour.fouruniquebodydex16.text_3"] = "shadowed the Auspex for the rest of his days.",
	["game.equipment_flavour.fouruniquebodydex2.text_1"] = "To catch an animal, think like an animal.",
	["game.equipment_flavour.fouruniquebodydex3.text_1"] = "The blasted oak stands forever.",
	["game.equipment_flavour.fouruniquebodydex4.text_1"] = "The desert is ever flowing.",
	["game.equipment_flavour.fouruniquebodydex5.text_1"] = "\"I carry neither food nor drink. I rely on the charity",
	["game.equipment_flavour.fouruniquebodydex5.text_2"] = "of my fellow wayfarers. Dead men are generous men.\"",
	["game.equipment_flavour.fouruniquebodydex5.text_3"] = "- Taruk of the Wildmen",
	["game.equipment_flavour.fouruniquebodydex6.text_1"] = "Wraeclast has suffered many great disasters,",
	["game.equipment_flavour.fouruniquebodydex6.text_2"] = "but life always springs back anew.",
	["game.equipment_flavour.fouruniquebodydex7.text_1"] = "The truth lies inside every man, if you dig around.",
	["game.equipment_flavour.fouruniquebodydex7.text_2"] = "Many a confession was found in the bowels of Axiom.",
	["game.equipment_flavour.fouruniquebodydex8.text_1"] = "As the serpent wills.",
	["game.equipment_flavour.fouruniquebodydexint1.text_1"] = "\"Prepare the rack, boy. And be careful with those hooks!\"",
	["game.equipment_flavour.fouruniquebodydexint1.text_2"] = "- the Master Torturer's last words",
	["game.equipment_flavour.fouruniquebodydexint13.text_1"] = "Curse their vile Council,",
	["game.equipment_flavour.fouruniquebodydexint13.text_2"] = "They cast me aside as if I am some bastard child.",
	["game.equipment_flavour.fouruniquebodydexint13.text_3"] = "If they only knew the power I possess.",
	["game.equipment_flavour.fouruniquebodydexint14.text_1"] = "A gift from the Draíocht, lost in Darkness.",
	["game.equipment_flavour.fouruniquebodydexint14.text_2"] = "The bronze hums. The cloth sighs.",
	["game.equipment_flavour.fouruniquebodydexint14.text_3"] = "Living pieces of her, yearning to exist.",
	["game.equipment_flavour.fouruniquebodydexint2.text_1"] = "It was in this forsaken land, where mists shroud the world in mystery,",
	["game.equipment_flavour.fouruniquebodydexint2.text_2"] = "that thieves, murderers, and outcasts, sought refuge.",
	["game.equipment_flavour.fouruniquebodydexint3.text_1"] = "Born among the high peaks, many Mutewind",
	["game.equipment_flavour.fouruniquebodydexint3.text_2"] = "live their entire lives in snow and ice.",
	["game.equipment_flavour.fouruniquebodydexint4.text_1"] = "Be not where death falls.",
	["game.equipment_flavour.fouruniquebodydexint5.text_1"] = "In all things, control.",
	["game.equipment_flavour.fouruniquebodydexint6.text_1"] = "Mortality is a curse.",
	["game.equipment_flavour.fouruniquebodydexint6.text_2"] = "The cure is simple.",
	["game.equipment_flavour.fouruniquebodyint1.text_1"] = "Faith springs abundant at the edge of death.",
	["game.equipment_flavour.fouruniquebodyint12.text_1"] = "Reap what others have sown",
	["game.equipment_flavour.fouruniquebodyint12.text_2"] = "Muster them from their graves",
	["game.equipment_flavour.fouruniquebodyint12.text_3"] = "Parade them for your pleasure",
	["game.equipment_flavour.fouruniquebodyint12.text_4"] = "Zealots in mortis enslaved",
	["game.equipment_flavour.fouruniquebodyint13.text_1"] = "When the throat roars,",
	["game.equipment_flavour.fouruniquebodyint13.text_2"] = "As eyes weep,",
	["game.equipment_flavour.fouruniquebodyint13.text_3"] = "When the hand grips hard",
	["game.equipment_flavour.fouruniquebodyint13.text_4"] = "With trembling fingers,",
	["game.equipment_flavour.fouruniquebodyint13.text_5"] = "When belly twists",
	["game.equipment_flavour.fouruniquebodyint13.text_6"] = "Yet legs stand strong,",
	["game.equipment_flavour.fouruniquebodyint13.text_7"] = "That is the work",
	["game.equipment_flavour.fouruniquebodyint13.text_8"] = "Of the Defiant Heart.",
	["game.equipment_flavour.fouruniquebodyint14.text_1"] = "Hallowed Dordalus was cast into the pit as a heretic,",
	["game.equipment_flavour.fouruniquebodyint14.text_2"] = "but his piety was so great, he would not burn.",
	["game.equipment_flavour.fouruniquebodyint14.text_3"] = "He rose again, lauded, his faith forever changed...",
	["game.equipment_flavour.fouruniquebodyint14.text_4"] = "but not the way the Templar believed.",
	["game.equipment_flavour.fouruniquebodyint2.text_1"] = "The soul cannot flourish in a doubting mind.",
	["game.equipment_flavour.fouruniquebodyint3.text_1"] = "Suspicion is a sinister shadow slithering in the soul.",
	["game.equipment_flavour.fouruniquebodyint4.text_1"] = "Fueled by the blackness in the hearts of men,",
	["game.equipment_flavour.fouruniquebodyint4.text_2"] = "the armies of Saresh were just as relentless.",
	["game.equipment_flavour.fouruniquebodyint5.text_1"] = "He who sows an ember shall reap an inferno.",
	["game.equipment_flavour.fouruniquebodyint6.text_1"] = "In its final era, the roofs of Keth were rife with",
	["game.equipment_flavour.fouruniquebodyint6.text_2"] = "anything and everything that could hold water...",
	["game.equipment_flavour.fouruniquebodyint6.text_3"] = "should the opportunity arise.",
	["game.equipment_flavour.fouruniquebodyint7.text_1"] = "A faith born of flesh.",
	["game.equipment_flavour.fouruniquebodyint8.text_1"] = "My Soul is your Strength",
	["game.equipment_flavour.fouruniquebodyint8.text_2"] = "My Price is your Blood",
	["game.equipment_flavour.fouruniquebodyint9.text_1"] = "The tale-women of old knew how to build anticipation.",
	["game.equipment_flavour.fouruniquebodystr1.text_1"] = "It is safer to be feared than to be loved.",
	["game.equipment_flavour.fouruniquebodystr12.text_1"] = "The turtle's shell one day becomes its tomb.",
	["game.equipment_flavour.fouruniquebodystr14.text_1"] = "The warrior who fears will fall.",
	["game.equipment_flavour.fouruniquebodystr2.text_1"] = "An Ezomyte endures.",
	["game.equipment_flavour.fouruniquebodystr3.text_1"] = "In death, the legendary boar's tusks were turned",
	["game.equipment_flavour.fouruniquebodystr3.text_2"] = "to the slaying of Phaaryl's Eternal oppressors.",
	["game.equipment_flavour.fouruniquebodystr4.text_1"] = "That most legendary caravan bandit had",
	["game.equipment_flavour.fouruniquebodystr4.text_2"] = "one rule: never let them see you flinch.",
	["game.equipment_flavour.fouruniquebodystr5.text_1"] = "Not the sound of thunder on the wind, but the",
	["game.equipment_flavour.fouruniquebodystr5.text_2"] = "rhoaback riders—death charging from the sands.",
	["game.equipment_flavour.fouruniquebodystr6.text_1"] = "Knowing she could outlast any opponent,",
	["game.equipment_flavour.fouruniquebodystr6.text_2"] = "Wrashmin fought not to win, but to delay.",
	["game.equipment_flavour.fouruniquebodystr7.text_1"] = "The toughest armour is the trust of your people.",
	["game.equipment_flavour.fouruniquebodystr8.text_1"] = "Some would question if the risk was worth it.",
	["game.equipment_flavour.fouruniquebodystr8.text_2"] = "The rest were already dead.",
	["game.equipment_flavour.fouruniquebodystrdex1.text_1"] = "For those noble families obsessed",
	["game.equipment_flavour.fouruniquebodystrdex1.text_2"] = "with keeping their bloodline pure,",
	["game.equipment_flavour.fouruniquebodystrdex1.text_3"] = "there was a price to pay...",
	["game.equipment_flavour.fouruniquebodystrdex11.text_1"] = "Whiff of cold, tiny spark, faintest flicker in the dark.",
	["game.equipment_flavour.fouruniquebodystrdex11.text_2"] = "Embers swirl, ice takes form, sky exposed - Death's perfect storm.",
	["game.equipment_flavour.fouruniquebodystrdex11.text_3"] = "Frost and thunder, flames shine bright, ruin walks the land tonight.",
	["game.equipment_flavour.fouruniquebodystrdex11.text_4"] = "By your hand they dance and bend, wield them and brook no end.",
	["game.equipment_flavour.fouruniquebodystrdex14.text_1"] = "\"What are you lot looking at? We're",
	["game.equipment_flavour.fouruniquebodystrdex14.text_2"] = "under fire! Get to your stations!\"",
	["game.equipment_flavour.fouruniquebodystrdex14.text_3"] = "- Captain Sventura, the Unlucky",
	["game.equipment_flavour.fouruniquebodystrdex2.text_1"] = "In the mists they dwell,",
	["game.equipment_flavour.fouruniquebodystrdex2.text_2"] = "forever hungry,",
	["game.equipment_flavour.fouruniquebodystrdex2.text_3"] = "forever cold.",
	["game.equipment_flavour.fouruniquebodystrdex3.text_1"] = "A power unknown aids your own.",
	["game.equipment_flavour.fouruniquebodystrdex4.text_1"] = "His isolation caused him to treasure",
	["game.equipment_flavour.fouruniquebodystrdex4.text_2"] = "their companionship all the more.",
	["game.equipment_flavour.fouruniquebodystrdex5.text_1"] = "There is no safer place",
	["game.equipment_flavour.fouruniquebodystrdex5.text_2"] = "Than the Belly of the Beast",
	["game.equipment_flavour.fouruniquebodystrdex6.text_1"] = "\"This was the first step in some grand design,",
	["game.equipment_flavour.fouruniquebodystrdex6.text_2"] = "lost to the ages, now ours to decipher.\"",
	["game.equipment_flavour.fouruniquebodystrdex6.text_3"] = "- Dominus, High Templar",
	["game.equipment_flavour.fouruniquebodystrdex7.text_1"] = "That day, both the Unblinking Eye and",
	["game.equipment_flavour.fouruniquebodystrdex7.text_2"] = "their enemies stood in silence. That day,",
	["game.equipment_flavour.fouruniquebodystrdex7.text_3"] = "the sky was clear, but it was raining.",
	["game.equipment_flavour.fouruniquebodystrdex8.text_1"] = "The world churned during the Great Wasting.",
	["game.equipment_flavour.fouruniquebodystrdex8.text_2"] = "Tawhoa may have stilled the rioting earth,",
	["game.equipment_flavour.fouruniquebodystrdex8.text_3"] = "but it was Valako that tamed the broken sky.",
	["game.equipment_flavour.fouruniquebodystrdex9.text_1"] = "\"I will never forget. I will carry your memory",
	["game.equipment_flavour.fouruniquebodystrdex9.text_2"] = "forward, all of you, from this ghastly Vale.\"",
	["game.equipment_flavour.fouruniquebodystrdex9.text_3"] = "- Artair, last survivor of the Ogham rebellion",
	["game.equipment_flavour.fouruniquebodystrdexint2.text_1"] = "\"When you have nothing to hide,",
	["game.equipment_flavour.fouruniquebodystrdexint2.text_2"] = "you have nothing to fear.\"",
	["game.equipment_flavour.fouruniquebodystrdexint2.text_3"] = "- Atziri, Queen of the Vaal",
	["game.equipment_flavour.fouruniquebodystrint1.text_1"] = "The gleam of the night and howling teeth alike could not abate the rising of the sun.",
	["game.equipment_flavour.fouruniquebodystrint11.text_1"] = "Faith does not make us invulnerable.",
	["game.equipment_flavour.fouruniquebodystrint11.text_2"] = "It makes us immortal.",
	["game.equipment_flavour.fouruniquebodystrint12.text_1"] = "The Twilight Order rejected the gods, choosing",
	["game.equipment_flavour.fouruniquebodystrint12.text_2"] = "instead to put their faith in each other.",
	["game.equipment_flavour.fouruniquebodystrint14.text_1"] = "The collector need not even speak. Each ring",
	["game.equipment_flavour.fouruniquebodystrint14.text_2"] = "regaled them with tales of his conquest.",
	["game.equipment_flavour.fouruniquebodystrint15.text_1"] = "His latent potential unleashed itself, a beast",
	["game.equipment_flavour.fouruniquebodystrint15.text_2"] = "bursting from its shackles. Each strike of Farrow's",
	["game.equipment_flavour.fouruniquebodystrint15.text_3"] = "hammer rang out a song for the First Ones.",
	["game.equipment_flavour.fouruniquebodystrint16.text_1"] = "\"Hold firm. Let no word but the Mothers' turn your head.",
	["game.equipment_flavour.fouruniquebodystrint16.text_2"] = "Through your unfaltering fealty, you achieve perfection.\"",
	["game.equipment_flavour.fouruniquebodystrint3.text_1"] = "When Solaris closes her burning eye",
	["game.equipment_flavour.fouruniquebodystrint3.text_2"] = "At the end of time,",
	["game.equipment_flavour.fouruniquebodystrint3.text_3"] = "the world will perish in ice.",
	["game.equipment_flavour.fouruniquebodystrint4.text_1"] = "\"Do not despair! Give yourself to the woods!",
	["game.equipment_flavour.fouruniquebodystrint4.text_2"] = "Become empty, and the Goddess will find you.",
	["game.equipment_flavour.fouruniquebodystrint4.text_3"] = "From within her roots... you shall be restored.\"",
	["game.equipment_flavour.fouruniquebodystrint4.text_4"] = "- Cirel of Caer Tarth",
	["game.equipment_flavour.fouruniquebodystrint5.text_1"] = "Although a great leader during the war,",
	["game.equipment_flavour.fouruniquebodystrint5.text_2"] = "Voll proved disastrous in times of peace.",
	["game.equipment_flavour.fouruniquebodystrint6.text_1"] = "The greatest mistakes cause suffering",
	["game.equipment_flavour.fouruniquebodystrint6.text_2"] = "long after they have been made",
	["game.equipment_flavour.fouruniquebodystrint7.text_1"] = "Through every great purge, and every fiery inquisition,",
	["game.equipment_flavour.fouruniquebodystrint7.text_2"] = "the Twilight Order endured in secret.",
	["game.equipment_flavour.fouruniquebodystrint8.text_1"] = "\"Move in ways your enemy does not expect.",
	["game.equipment_flavour.fouruniquebodystrint8.text_2"] = "Confuse them with elegance and grace.",
	["game.equipment_flavour.fouruniquebodystrint8.text_3"] = "They'll never see the axe coming.\"",
	["game.equipment_flavour.fouruniquebodystrint8.text_4"] = "- Rakiata, Chieftain of the Tasalio Tribe",
	["game.equipment_flavour.fouruniquebodystrint9.text_1"] = "It is often said of nobles that they live off their",
	["game.equipment_flavour.fouruniquebodystrint9.text_2"] = "peasants... sometimes, it's truer than any suspect.",
	["game.equipment_flavour.fouruniquebootsdex2.text_1"] = "The druids walk the Grelwood without fear.",
	["game.equipment_flavour.fouruniquebootsdex3.text_1"] = "All your tomorrows lie ahead of you,",
	["game.equipment_flavour.fouruniquebootsdex3.text_2"] = "unknown and snarled to the very last.",
	["game.equipment_flavour.fouruniquebootsdex4.text_1"] = "Where legends tread,",
	["game.equipment_flavour.fouruniquebootsdex4.text_2"] = "the world hearkens.",
	["game.equipment_flavour.fouruniquebootsdex5.text_1"] = "Banished for his tragic failure,",
	["game.equipment_flavour.fouruniquebootsdex5.text_2"] = "Erian learned to hunt to survive.",
	["game.equipment_flavour.fouruniquebootsdex9.text_1"] = "\"Those who dance are considered insane",
	["game.equipment_flavour.fouruniquebootsdex9.text_2"] = "by those who cannot hear the music.\"",
	["game.equipment_flavour.fouruniquebootsdex9.text_3"] = "- Atziri, Queen of the Vaal",
	["game.equipment_flavour.fouruniquebootsdexint2.text_1"] = "The cursed ones march forever,",
	["game.equipment_flavour.fouruniquebootsdexint2.text_2"] = "On their hopeless, last endeavour.",
	["game.equipment_flavour.fouruniquebootsdexint3.text_1"] = "The combat stance used by Vaal nobles",
	["game.equipment_flavour.fouruniquebootsdexint3.text_2"] = "was as elegant as it was deadly.",
	["game.equipment_flavour.fouruniquebootsint1.text_1"] = "Blessed are those who tend the Grove.",
	["game.equipment_flavour.fouruniquebootsint2.text_1"] = "All the world is my home.",
	["game.equipment_flavour.fouruniquebootsint3.text_1"] = "The dead man walks where",
	["game.equipment_flavour.fouruniquebootsint3.text_2"] = "the living fear to tread.",
	["game.equipment_flavour.fouruniquebootsint4.text_1"] = "Wonders abound at death's door.",
	["game.equipment_flavour.fouruniquebootsint5.text_1"] = "The mocking wind, a shielding spell,",
	["game.equipment_flavour.fouruniquebootsint5.text_2"] = "The haunting screams, a maddening hell",
	["game.equipment_flavour.fouruniquebootsstr1.text_1"] = "A wall of steel and muscle.",
	["game.equipment_flavour.fouruniquebootsstr2.text_1"] = "Natural decay can be twisted to dark ends.",
	["game.equipment_flavour.fouruniquebootsstr3.text_1"] = "We move to be closer to her, but the distance yet grows.",
	["game.equipment_flavour.fouruniquebootsstr4.text_1"] = "The truly mighty are never outnumbered.",
	["game.equipment_flavour.fouruniquebootsstr5.text_1"] = "As the sun rises and the light approaches,",
	["game.equipment_flavour.fouruniquebootsstr5.text_2"] = "so too shall your enemies fear you.",
	["game.equipment_flavour.fouruniquebootsstrdex1.text_1"] = "Some search forever for their path.",
	["game.equipment_flavour.fouruniquebootsstrdex2.text_1"] = "\"Sirrius flew on wings of light, faster than wind, faster",
	["game.equipment_flavour.fouruniquebootsstrdex2.text_2"] = "than thought. But try as he might to outrun the darkness,",
	["game.equipment_flavour.fouruniquebootsstrdex2.text_3"] = "it was there, at every turn, waiting for him.\"",
	["game.equipment_flavour.fouruniquebootsstrdex2.text_4"] = "- Azmerian legend",
	["game.equipment_flavour.fouruniquebootsstrdex3.text_1"] = "The storm cannot sway those of sure footing.",
	["game.equipment_flavour.fouruniquebootsstrdex4.text_1"] = "\"Captain Hiff Greybeard accomplished what nary a Brinerot",
	["game.equipment_flavour.fouruniquebootsstrdex4.text_2"] = "could: he died of old age. Almost had him a dozen times",
	["game.equipment_flavour.fouruniquebootsstrdex4.text_3"] = "meself, if it weren't for that damn leg of his... crafty shite...\"",
	["game.equipment_flavour.fouruniquebootsstrint2.text_1"] = "Tempest's power given form,",
	["game.equipment_flavour.fouruniquebootsstrint2.text_2"] = "Flee before the walking storm.",
	["game.equipment_flavour.fouruniquebootsstrint9.text_1"] = "\"Soar. Be swift. Let none trespass here, from",
	["game.equipment_flavour.fouruniquebootsstrint9.text_2"] = "above or below, lest your purpose be forfeit.\"",
	["game.equipment_flavour.fouruniquebow1.text_1"] = "\"I loosed a volley of arrows into the heart of the man",
	["game.equipment_flavour.fouruniquebow1.text_2"] = "who slew my beloved. There was no satisfaction, no",
	["game.equipment_flavour.fouruniquebow1.text_3"] = "healing, no revenge. There was only... emptiness.\"",
	["game.equipment_flavour.fouruniquebow13.text_1"] = "\"Kinslayer, you dishonour your own traditions to turn the tide of battle!",
	["game.equipment_flavour.fouruniquebow13.text_2"] = "Let us see which is stronger... Karui savagery or the might of the Empire!\"",
	["game.equipment_flavour.fouruniquebow13.text_3"] = "- General Marceus Lioneye",
	["game.equipment_flavour.fouruniquebow14.text_1"] = "As the Maji approached the edge of Nothingness, she strung",
	["game.equipment_flavour.fouruniquebow14.text_2"] = "fragments of the Wildwood's carcass together. When she",
	["game.equipment_flavour.fouruniquebow14.text_3"] = "nocked her arrow, she pulled upon the elements of life itself.",
	["game.equipment_flavour.fouruniquebow2.text_1"] = "\"The rain of a thousand quills that whittle",
	["game.equipment_flavour.fouruniquebow2.text_2"] = "present into past, life into death.\"",
	["game.equipment_flavour.fouruniquebow2.text_3"] = "- Rigwald of the Ezomytes",
	["game.equipment_flavour.fouruniquebow3.text_1"] = "Each crest was a Thane's word, bolted to Ivor's bow.",
	["game.equipment_flavour.fouruniquebow3.text_2"] = "They would join the Count's side, or die by his hands.",
	["game.equipment_flavour.fouruniquebow4.text_1"] = "The forests of the Vastiri held many secrets",
	["game.equipment_flavour.fouruniquebow4.text_2"] = "mystical and dark. Men learned not to wander,",
	["game.equipment_flavour.fouruniquebow4.text_3"] = "lest they return with a strange new purpose.",
	["game.equipment_flavour.fouruniquebow5.text_1"] = "\"Toasted or frozen",
	["game.equipment_flavour.fouruniquebow5.text_2"] = "Or twitching in the light",
	["game.equipment_flavour.fouruniquebow5.text_3"] = "I'm not fussy",
	["game.equipment_flavour.fouruniquebow5.text_4"] = "And neither is Death.\"",
	["game.equipment_flavour.fouruniquebow5.text_5"] = "- Koralus Doomfletch",
	["game.equipment_flavour.fouruniquebow6.text_1"] = "The mournful music of the strings,",
	["game.equipment_flavour.fouruniquebow6.text_2"] = "The creaking arch, the arrow sings.",
	["game.equipment_flavour.fouruniquebow6.text_3"] = "A choking cry, a rattled breath,",
	["game.equipment_flavour.fouruniquebow6.text_4"] = "The Reaper's Song, the Harp of Death.",
	["game.equipment_flavour.fouruniquebow7.text_1"] = "The eldritch storm descended upon us, and bruised lightning",
	["game.equipment_flavour.fouruniquebow7.text_2"] = "rained down. Metal withered and flesh melted before its",
	["game.equipment_flavour.fouruniquebow7.text_3"] = "arcane power. There was no escape, no shelter. Only despair.",
	["game.equipment_flavour.fouruniquebow8.text_1"] = "A hundred blind heads, each seeking the taste of prey on the air.",
	["game.equipment_flavour.fouruniquebow9.text_1"] = "The power of the Allflame rends",
	["game.equipment_flavour.fouruniquebow9.text_2"] = "souls just as easily as flesh.",
	["game.equipment_flavour.fouruniquebreach1.text_1"] = "We happily give our limbs.",
	["game.equipment_flavour.fouruniquebreach1.text_2"] = "A net woven to keep safe the bones of the Lords.",
	["game.equipment_flavour.fouruniquebreach2.text_1"] = "She thinks and we act.",
	["game.equipment_flavour.fouruniquebreach2.text_2"] = "She acts and we think.",
	["game.equipment_flavour.fouruniquebreach2.text_3"] = "Fragments of the whole that washes clean the skies.",
	["game.equipment_flavour.fouruniquebreach3.text_1"] = "The limit of our knowledge is a barrier",
	["game.equipment_flavour.fouruniquebreach3.text_2"] = "that protects us from ourselves.",
	["game.equipment_flavour.fouruniquebreach4a.text_1"] = "We are his blood.",
	["game.equipment_flavour.fouruniquebreach4a.text_2"] = "Through us he carries his burning message.",
	["game.equipment_flavour.fouruniquebreach4b.text_1"] = "But the fool did not bow.",
	["game.equipment_flavour.fouruniquebreach4b.text_2"] = "The fool stood and questioned.",
	["game.equipment_flavour.fouruniquebreach4b.text_3"] = "And the fool was unwritten.",
	["game.equipment_flavour.fouruniquebreach4c.text_1"] = "A single moment sets in motion an eternal fall,",
	["game.equipment_flavour.fouruniquebreach4c.text_2"] = "beneath which all are buried.",
	["game.equipment_flavour.fouruniquecharm1.text_1"] = "\"Even in the face of the Winter of the World,",
	["game.equipment_flavour.fouruniquecharm1.text_2"] = "life found a way. The Spirit always provides.\"",
	["game.equipment_flavour.fouruniquecharm10.text_1"] = "The sea swells, the sky thunders; two ships tilt at odds.",
	["game.equipment_flavour.fouruniquecharm10.text_2"] = "Flashes of light show only swinging axes... and a grin.",
	["game.equipment_flavour.fouruniquecharm11.text_1"] = "Among the Templars, a secret few ate the sins of others.",
	["game.equipment_flavour.fouruniquecharm11.text_2"] = "They bore this burden to empower their hidden Order.",
	["game.equipment_flavour.fouruniquecharm2.text_1"] = "Wraeclast has known too few true heroes.",
	["game.equipment_flavour.fouruniquecharm2.text_2"] = "It remembers those that stood in defiance.",
	["game.equipment_flavour.fouruniquecharm3.text_1"] = "Devotees of the Goddess of Lust",
	["game.equipment_flavour.fouruniquecharm3.text_2"] = "needed never fear her sting.",
	["game.equipment_flavour.fouruniquecharm4.text_1"] = "They found a crying child tied to a frozen pyre.",
	["game.equipment_flavour.fouruniquecharm4.text_2"] = "She was clad in ice, but the village was ash.",
	["game.equipment_flavour.fouruniquecharm5.text_1"] = "The most beloved member of every Brinerot crew",
	["game.equipment_flavour.fouruniquecharm5.text_2"] = "is the one that refuses to do any actual work.",
	["game.equipment_flavour.fouruniquecharm6.text_1"] = "\"It may be centuries hence, but I still hold utmost faith.",
	["game.equipment_flavour.fouruniquecharm6.text_2"] = "The Saviour will rise, and mankind will be free.\"",
	["game.equipment_flavour.fouruniquecharm7.text_1"] = "\"When the headsman's blade swings,",
	["game.equipment_flavour.fouruniquecharm7.text_2"] = "your last moments stretch to eternity.\"",
	["game.equipment_flavour.fouruniquecharm7.text_3"] = "- Vorm, the Twice-Pardoned",
	["game.equipment_flavour.fouruniquecharm8.text_1"] = "Kaom was not known for his restraint.",
	["game.equipment_flavour.fouruniquecharm9.text_1"] = "\"To scrape the sky,",
	["game.equipment_flavour.fouruniquecharm9.text_2"] = "to touch the clouds themselves,",
	["game.equipment_flavour.fouruniquecharm9.text_3"] = "is to know true freedom.\"",
	["game.equipment_flavour.fouruniquecharm9.text_4"] = "- Mutewind saying",
	["game.equipment_flavour.fouruniquecorruption1.text_1"] = "\"Ghorr knows only hunger, only ravenous feasting.",
	["game.equipment_flavour.fouruniquecorruption1.text_2"] = "It will consume all that lives, and more!\"",
	["game.equipment_flavour.fouruniquecorruption1.text_3"] = "- Rantings of a Templar prisoner, page fourteen",
	["game.equipment_flavour.fouruniquecorruption2.text_1"] = "\"All Beidat desires is a foothold, a grip on your flesh,",
	["game.equipment_flavour.fouruniquecorruption2.text_2"] = "on the world... he will offer you anything to get it...\"",
	["game.equipment_flavour.fouruniquecorruption2.text_3"] = "- Rantings of a Templar prisoner, page thirty",
	["game.equipment_flavour.fouruniquecorruption3.text_1"] = "\"The mind at the center of the swarm... K'Tash does",
	["game.equipment_flavour.fouruniquecorruption3.text_2"] = "the thinking... but it has only one thought... hate.\"",
	["game.equipment_flavour.fouruniquecorruption3.text_3"] = "- Rantings of a Templar prisoner, page ninety-four",
	["game.equipment_flavour.fouruniquecrossbow1.text_1"] = "Sibilant promises surrounded them in the night.",
	["game.equipment_flavour.fouruniquecrossbow1.text_2"] = "All the travelers had to give him was their devotion...",
	["game.equipment_flavour.fouruniquecrossbow13.text_1"] = "\"And here we shall remain...",
	["game.equipment_flavour.fouruniquecrossbow13.text_2"] = "trapped in our symphony of eternal anguish.",
	["game.equipment_flavour.fouruniquecrossbow13.text_3"] = "Artist and Composer, their fates entwined for all of time.\"",
	["game.equipment_flavour.fouruniquecrossbow13.text_4"] = "- Adamantia Brektov, the Composer",
	["game.equipment_flavour.fouruniquecrossbow14.text_1"] = "\"The time has passed for diplomacy!",
	["game.equipment_flavour.fouruniquecrossbow14.text_2"] = "If they will not respect House Azadi,",
	["game.equipment_flavour.fouruniquecrossbow14.text_3"] = "then let them die gloriously... and loudly.",
	["game.equipment_flavour.fouruniquecrossbow14.text_4"] = "We are the masters of the Death Trades!\"",
	["game.equipment_flavour.fouruniquecrossbow14.text_5"] = "- Ratha Azadi",
	["game.equipment_flavour.fouruniquecrossbow2.text_1"] = "\"His approach to the gate was met with sounding trumpets",
	["game.equipment_flavour.fouruniquecrossbow2.text_2"] = "and an unfurling of banners. He never saw it coming.\"",
	["game.equipment_flavour.fouruniquecrossbow2.text_3"] = "- anonymous Brotherhood of Silence report",
	["game.equipment_flavour.fouruniquecrossbow5.text_1"] = "For those without a home in the Vastiri, the",
	["game.equipment_flavour.fouruniquecrossbow5.text_2"] = "hot day is harsh, but the chill night is far worse.",
	["game.equipment_flavour.fouruniquedelirium1.text_1"] = "A moment of calm before the battle can end the war.",
	["game.equipment_flavour.fouruniquedelirium2.text_1"] = "The Trickster God turned the very Day and Night against each other.",
	["game.equipment_flavour.fouruniquedelirium2.text_2"] = "What hope have you?",
	["game.equipment_flavour.fouruniquedelirium3.text_1"] = "What is life, but a dreamlike spiral of panic?",
	["game.equipment_flavour.fouruniquedelirium4.text_1"] = "The edges bend, the world flexes, the infinite spills into view.",
	["game.equipment_flavour.fouruniquedelirium5.text_1"] = "There is no light at the end of this inner strife,",
	["game.equipment_flavour.fouruniquedelirium5.text_2"] = "but the shadows eventually become home.",
	["game.equipment_flavour.fouruniqueexpedition1.text_1"] = "The priests found the Great Shield the night it fell to Middengard,",
	["game.equipment_flavour.fouruniqueexpedition1.text_2"] = "but it was the smiths who delved into the secrets it held.",
	["game.equipment_flavour.fouruniqueexpedition2.text_1"] = "The priests of the Kalguur keep faith through numbers",
	["game.equipment_flavour.fouruniqueexpedition2.text_2"] = "and calculation, not unprovable promises.",
	["game.equipment_flavour.fouruniqueexpedition3.text_1"] = "Olroth the Gallant,",
	["game.equipment_flavour.fouruniqueexpedition3.text_2"] = "tireless and true,",
	["game.equipment_flavour.fouruniqueexpedition3.text_3"] = "he fights for me,",
	["game.equipment_flavour.fouruniqueexpedition3.text_4"] = "he fights for you!",
	["game.equipment_flavour.fouruniqueexpedition4.text_1"] = "\"True heroes grow stronger in the face of adversity.\"",
	["game.equipment_flavour.fouruniqueexpedition4.text_2"] = "- Fourth Tenet of the Knights of the Sun",
	["game.equipment_flavour.fouruniquefocus1.text_1"] = "The cry of death whispers in the wind.",
	["game.equipment_flavour.fouruniquefocus2.text_1"] = "A gift, a braid, of golden hair.",
	["game.equipment_flavour.fouruniquefocus2.text_2"] = "The war, forgotten.",
	["game.equipment_flavour.fouruniquefocus2.text_3"] = "The reason, remembered.",
	["game.equipment_flavour.fouruniquefocus3.text_1"] = "The horrors we imagined as children",
	["game.equipment_flavour.fouruniquefocus3.text_2"] = "still exist somewhere in the dark...",
	["game.equipment_flavour.fouruniquefocus4.text_1"] = "Obedience stretches beyond the grave.",
	["game.equipment_flavour.fouruniquefocus5.text_1"] = "Sinuous, entwined... inextricable.",
	["game.equipment_flavour.fouruniquefocus6.text_1"] = "A flash of blue, a stormcloud's kiss,",
	["game.equipment_flavour.fouruniquefocus6.text_2"] = "her motionless dance the pulse of bliss",
	["game.equipment_flavour.fouruniquefocus7.text_1"] = "Give him your body, and your burdens will follow.",
	["game.equipment_flavour.fouruniquefocus8.text_1"] = "The Vaal emptied their slaves of beating hearts,",
	["game.equipment_flavour.fouruniquefocus8.text_2"] = "and left a mountain of twitching dead.",
	["game.equipment_flavour.fouruniqueglovesdex1.text_1"] = "Fight with the ferocity of the First Ones.",
	["game.equipment_flavour.fouruniqueglovesdex2.text_1"] = "After the eruption, the skies turned grey,",
	["game.equipment_flavour.fouruniqueglovesdex2.text_2"] = "ash began to fall, and a chill set in...",
	["game.equipment_flavour.fouruniqueglovesdex4.text_1"] = "The devil finds work for idle hands.",
	["game.equipment_flavour.fouruniqueglovesdex5.text_1"] = "As the serpent shuns thought,",
	["game.equipment_flavour.fouruniqueglovesdex5.text_2"] = "It shuns fear.",
	["game.equipment_flavour.fouruniqueglovesdex5.text_3"] = "It strikes with the speed of wrath",
	["game.equipment_flavour.fouruniqueglovesdex5.text_4"] = "And the skill of compulsion.",
	["game.equipment_flavour.fouruniqueglovesdex6.text_1"] = "Maligaro operated effortlessly,",
	["game.equipment_flavour.fouruniqueglovesdex6.text_2"] = "with great speed and terrible consequences.",
	["game.equipment_flavour.fouruniqueglovesdex9.text_1"] = "If fear doesn't kill you, I will.",
	["game.equipment_flavour.fouruniqueglovesdexint1.text_1"] = "Ulcers, scabs, and pocks, the third army makes its claim.",
	["game.equipment_flavour.fouruniqueglovesdexint2.text_1"] = "\"Stitches? Wouldn't that defeat the purpose?\"",
	["game.equipment_flavour.fouruniqueglovesdexint2.text_2"] = "- Jeffry, Torturer's Apprentice",
	["game.equipment_flavour.fouruniqueglovesdexint5.text_1"] = "The darkest clouds clashed and coupled,",
	["game.equipment_flavour.fouruniqueglovesdexint5.text_2"] = "giving birth to four lightning children of hate.",
	["game.equipment_flavour.fouruniqueglovesdexint6.text_1"] = "The roar of the heavens",
	["game.equipment_flavour.fouruniqueglovesdexint6.text_2"] = "Strikes more than fear",
	["game.equipment_flavour.fouruniqueglovesdexint6.text_3"] = "Into the hearts of Man",
	["game.equipment_flavour.fouruniqueglovesint1.text_1"] = "Bloodshed on the crimson shores,",
	["game.equipment_flavour.fouruniqueglovesint1.text_2"] = "longing for the endless sea.",
	["game.equipment_flavour.fouruniqueglovesint1.text_3"] = "Treasures, life, I'd give it all",
	["game.equipment_flavour.fouruniqueglovesint1.text_4"] = "just to capture thee.",
	["game.equipment_flavour.fouruniqueglovesint2.text_1"] = "You can be the wick or the wax. Either way, your light goes out and mine goes on.",
	["game.equipment_flavour.fouruniqueglovesint3.text_1"] = "While Doedre lacked Maligaro's sense of style,",
	["game.equipment_flavour.fouruniqueglovesint3.text_2"] = "she surpassed her master in pure malevolence.",
	["game.equipment_flavour.fouruniqueglovesint4.text_1"] = "Reality is a puzzle. Ingenuity is power.",
	["game.equipment_flavour.fouruniqueglovesint5.text_1"] = "Xibaqua's treachery was met with divine fury.",
	["game.equipment_flavour.fouruniqueglovesint5.text_2"] = "One by one, the gods reclaimed their flesh,",
	["game.equipment_flavour.fouruniqueglovesint5.text_3"] = "until all that remained was a droplet of pure light:",
	["game.equipment_flavour.fouruniqueglovesint5.text_4"] = "The first Vaal.",
	["game.equipment_flavour.fouruniqueglovesint6.text_1"] = "Diamora sings not for hunger, but for longing.",
	["game.equipment_flavour.fouruniqueglovesint7.text_1"] = "\"Keep smiling. The deepest cut comes not from insults, but from false praise.\"",
	["game.equipment_flavour.fouruniqueglovesstr1.text_1"] = "\"You think us savages?\" mused the Red Wolf, as",
	["game.equipment_flavour.fouruniqueglovesstr1.text_2"] = "he pulled teeth from the Eternal's skull. \"I will",
	["game.equipment_flavour.fouruniqueglovesstr1.text_3"] = "show your kind the way of tooth and claw.\"",
	["game.equipment_flavour.fouruniqueglovesstr2.text_1"] = "The largest beings on Wraeclast",
	["game.equipment_flavour.fouruniqueglovesstr2.text_2"] = "are not flesh and blood.",
	["game.equipment_flavour.fouruniqueglovesstr3.text_1"] = "Why cling to your sanity? It offers you nothing.",
	["game.equipment_flavour.fouruniqueglovesstr3.text_2"] = "Surrender to me, and I will grant you everything.",
	["game.equipment_flavour.fouruniqueglovesstr4.text_1"] = "What is worse, the sting of the past, the pain of the present, or the fear of the future?",
	["game.equipment_flavour.fouruniqueglovesstr5.text_1"] = "\"The heart is the herald.",
	["game.equipment_flavour.fouruniqueglovesstr5.text_2"] = "It will tell me when it is best to strike.\"",
	["game.equipment_flavour.fouruniqueglovesstr5.text_3"] = "- Atziri, Queen of the Vaal",
	["game.equipment_flavour.fouruniqueglovesstr7.text_1"] = "\"I like my vassals at sword point,",
	["game.equipment_flavour.fouruniqueglovesstr7.text_2"] = "but my enemies as close as the hilt.\"",
	["game.equipment_flavour.fouruniqueglovesstr7.text_3"] = "- Emperor Chitus",
	["game.equipment_flavour.fouruniqueglovesstrdex1.text_1"] = "The whispers of the old gods hum through the iron. They demand a hero.",
	["game.equipment_flavour.fouruniqueglovesstrdex2.text_1"] = "Wealth is not to be borne lightly.",
	["game.equipment_flavour.fouruniqueglovesstrdex3.text_1"] = "Anticipation is a gift.",
	["game.equipment_flavour.fouruniqueglovesstrdex4.text_1"] = "Unlike the other gods, when he was born from the volcano,",
	["game.equipment_flavour.fouruniqueglovesstrdex4.text_2"] = "Valako rode the clouds of ash into the thundering sky.",
	["game.equipment_flavour.fouruniqueglovesstrdex5.text_1"] = "The strongest souls are forged through struggle and defeat.",
	["game.equipment_flavour.fouruniqueglovesstrint1.text_1"] = "Try as you like to hide the",
	["game.equipment_flavour.fouruniqueglovesstrint1.text_2"] = "blood on your hands.",
	["game.equipment_flavour.fouruniqueglovesstrint1.text_3"] = "You'll still know the truth.",
	["game.equipment_flavour.fouruniqueglovesstrint2.text_1"] = "Captivity breeds creativity.",
	["game.equipment_flavour.fouruniqueglovesstrint3.text_1"] = "The secret was lost with its maker.",
	["game.equipment_flavour.fouruniqueglovesstrint4.text_1"] = "Only once did Maligaro wonder if he'd gone too far.",
	["game.equipment_flavour.fouruniqueglovesstrint4.text_2"] = "His greatest success took three entire legions to capture.",
	["game.equipment_flavour.fouruniquehelmetdex1.text_1"] = "Beyond madness lies inspiration.",
	["game.equipment_flavour.fouruniquehelmetdex10.text_1"] = "The end always comes sooner than we think.",
	["game.equipment_flavour.fouruniquehelmetdex11.text_1"] = "Nature respects the strong",
	["game.equipment_flavour.fouruniquehelmetdex11.text_2"] = "And paints the snow red",
	["game.equipment_flavour.fouruniquehelmetdex11.text_3"] = "With the blood of the weak",
	["game.equipment_flavour.fouruniquehelmetdex2.text_1"] = "No metal slips as easily through the fingers as gold.",
	["game.equipment_flavour.fouruniquehelmetdex3.text_1"] = "No man burns alone.",
	["game.equipment_flavour.fouruniquehelmetdex5.text_1"] = "Ancient worshippers of the Greatwolf were overtaken",
	["game.equipment_flavour.fouruniquehelmetdex5.text_2"] = "by a ravenous hunger for all things mystical.",
	["game.equipment_flavour.fouruniquehelmetdex6.text_1"] = "\"Be vigilant, Nezahul! When the serpent is cornered, does it give up?",
	["game.equipment_flavour.fouruniquehelmetdex6.text_2"] = "No... It waits. Then it bites the first hand it finds.",
	["game.equipment_flavour.fouruniquehelmetdex6.text_3"] = "The danger of numbers is all in your mind!\"",
	["game.equipment_flavour.fouruniquehelmetdex6.text_4"] = "- Viper Napuatzi, instructing Royal Commander Nezahul",
	["game.equipment_flavour.fouruniquehelmetdex7.text_1"] = "Brinerot pirates live in a perpetual blaze of glory,",
	["game.equipment_flavour.fouruniquehelmetdex7.text_2"] = "pushing their luck right to the end.",
	["game.equipment_flavour.fouruniquehelmetdex8.text_1"] = "There was no hero made out of Starkonja's death,",
	["game.equipment_flavour.fouruniquehelmetdex8.text_2"] = "but merely a long sleep made eternal.",
	["game.equipment_flavour.fouruniquehelmetdex9.text_1"] = "Give of your heated passions.",
	["game.equipment_flavour.fouruniquehelmetdex9.text_2"] = "Give of your cold resolve.",
	["game.equipment_flavour.fouruniquehelmetdex9.text_3"] = "You will be repaid.",
	["game.equipment_flavour.fouruniquehelmetdexint1.text_1"] = "The roots burrow deeper, unveiling the wood's bounty...",
	["game.equipment_flavour.fouruniquehelmetdexint2.text_1"] = "A terror of ancient times, his identity",
	["game.equipment_flavour.fouruniquehelmetdexint2.text_2"] = "remains lost... but his power does not.",
	["game.equipment_flavour.fouruniquehelmetdexint3.text_1"] = "For none of us are as cruel as all of us.",
	["game.equipment_flavour.fouruniquehelmetdexint4.text_1"] = "Remaining unseen, the Dishonoured Assassin struck",
	["game.equipment_flavour.fouruniquehelmetdexint4.text_2"] = "only in the depths of the harshest sandstorms.",
	["game.equipment_flavour.fouruniquehelmetdexint5.text_1"] = "\"A queen should be seen, admired, but never touched.\"",
	["game.equipment_flavour.fouruniquehelmetdexint5.text_2"] = "- Atziri, Queen of the Vaal",
	["game.equipment_flavour.fouruniquehelmetdexint6.text_1"] = "\"The ice seared his naked feet",
	["game.equipment_flavour.fouruniquehelmetdexint6.text_2"] = "As the lightning stilled his heart,",
	["game.equipment_flavour.fouruniquehelmetdexint6.text_3"] = "But it was the flames upon his lover's face",
	["game.equipment_flavour.fouruniquehelmetdexint6.text_4"] = "That roused him to vengeance.\"",
	["game.equipment_flavour.fouruniquehelmetdexint6.text_5"] = "- From 'The Three Dragons' by Victario of Sarn",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_1"] = "The sky tore asunder, black cleaving upon blue",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_2"] = "The end of life, of Time, with no escape",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_3"] = "But they found a fragment, a void, a haven",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_4"] = "And there they waited, as it all began again",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_5"] = "Dark will, dark knowledge, enemies of Fate",
	["game.equipment_flavour.fouruniquehelmetdexint8.text_6"] = "They know your mind, because they remember",
	["game.equipment_flavour.fouruniquehelmetint1.text_1"] = "Lift it lightly, don it slow.",
	["game.equipment_flavour.fouruniquehelmetint1.text_2"] = "The spikes point out and in, you know.",
	["game.equipment_flavour.fouruniquehelmetint11.text_1"] = "Where the body's limits begin,",
	["game.equipment_flavour.fouruniquehelmetint11.text_2"] = "the mind's limits end.",
	["game.equipment_flavour.fouruniquehelmetint2.text_1"] = "The spirit hungers for the flesh.",
	["game.equipment_flavour.fouruniquehelmetint3.text_1"] = "Tale-women do not fight as dekharas.",
	["game.equipment_flavour.fouruniquehelmetint3.text_2"] = "They command a power all their own.",
	["game.equipment_flavour.fouruniquehelmetint4.text_1"] = "Keep your heart as ice,",
	["game.equipment_flavour.fouruniquehelmetint4.text_2"] = "lest your passions stir.",
	["game.equipment_flavour.fouruniquehelmetint5.text_1"] = "From the flesh of the gods, Xibaqua was born.",
	["game.equipment_flavour.fouruniquehelmetint5.text_2"] = "From the carnage of Xibaqua, we were born.",
	["game.equipment_flavour.fouruniquehelmetint5.text_3"] = "It is our duty to return to the gods what was once theirs.",
	["game.equipment_flavour.fouruniquehelmetint6.text_1"] = "They screamed her name in adulation as they gave",
	["game.equipment_flavour.fouruniquehelmetint6.text_2"] = "their very lives. She looked on with impatience.",
	["game.equipment_flavour.fouruniquehelmetint7.text_1"] = "Turning, gazing, blinking,",
	["game.equipment_flavour.fouruniquehelmetint7.text_2"] = "behold the eyes of void.",
	["game.equipment_flavour.fouruniquehelmetint7.text_3"] = "Burning, razing, drinking,",
	["game.equipment_flavour.fouruniquehelmetint7.text_4"] = "your mind is destroyed.",
	["game.equipment_flavour.fouruniquehelmetint8.text_1"] = "\"The sharper the pain, the sharper the mind.",
	["game.equipment_flavour.fouruniquehelmetint8.text_2"] = "A curious paradox.\"",
	["game.equipment_flavour.fouruniquehelmetint8.text_3"] = "- Shavronne of Umbra",
	["game.equipment_flavour.fouruniquehelmetstr1a.text_1"] = "The younger brother waded into battle, shrugging off blows.",
	["game.equipment_flavour.fouruniquehelmetstr1b.text_1"] = "The older brother retained calm in the midst of fury.",
	["game.equipment_flavour.fouruniquehelmetstr2.text_1"] = "Centuries of servitude, a day",
	["game.equipment_flavour.fouruniquehelmetstr2.text_2"] = "of glory, an eternity of death.",
	["game.equipment_flavour.fouruniquehelmetstr3.text_1"] = "The beasts we fear the most",
	["game.equipment_flavour.fouruniquehelmetstr3.text_2"] = "are the ones who dwell in total darkness.",
	["game.equipment_flavour.fouruniquehelmetstr4.text_1"] = "We may fight, and we may die, but in these",
	["game.equipment_flavour.fouruniquehelmetstr4.text_2"] = "moments of blood and battle, we truly live.",
	["game.equipment_flavour.fouruniquehelmetstr5.text_1"] = "May you never hear it toll.",
	["game.equipment_flavour.fouruniquehelmetstr6.text_1"] = "Only the High Priests could enact the sacrifices,",
	["game.equipment_flavour.fouruniquehelmetstr6.text_2"] = "but all who witnessed shared in exultation.",
	["game.equipment_flavour.fouruniquehelmetstr8.text_1"] = "An eye for an eye makes the whole world dead.",
	["game.equipment_flavour.fouruniquehelmetstrdex1.text_1"] = "In the end, even heroes fade away.",
	["game.equipment_flavour.fouruniquehelmetstrdex2.text_1"] = "Sometimes patching up your",
	["game.equipment_flavour.fouruniquehelmetstrdex2.text_2"] = "equipment gets out of hand.",
	["game.equipment_flavour.fouruniquehelmetstrdex3.text_1"] = "Let the rider's aim be true.",
	["game.equipment_flavour.fouruniquehelmetstrdex4.text_1"] = "He never spoke a word. His opponents imagined",
	["game.equipment_flavour.fouruniquehelmetstrdex4.text_2"] = "their own personal mockeries, most cruel.",
	["game.equipment_flavour.fouruniquehelmetstrdex5.text_1"] = "Familiarity breeds contempt.",
	["game.equipment_flavour.fouruniquehelmetstrdex7.text_1"] = "\"What lies beneath your feet?!\"",
	["game.equipment_flavour.fouruniquehelmetstrdex7.text_2"] = "\"Sacred ground, watered with tears of blood!\"",
	["game.equipment_flavour.fouruniquehelmetstrdex9.text_1"] = "\"Focus. Hone your mind. Your lessers rely on the tangible.",
	["game.equipment_flavour.fouruniquehelmetstrdex9.text_2"] = "Shed your senses, and raze them from this physical realm.\"",
	["game.equipment_flavour.fouruniquehelmetstrint1.text_1"] = "An endless river of bodies lie in the wake of ambition.",
	["game.equipment_flavour.fouruniquehelmetstrint2.text_1"] = "Heavy is the head.",
	["game.equipment_flavour.fouruniquehelmetstrint3.text_1"] = "A lightless world",
	["game.equipment_flavour.fouruniquehelmetstrint3.text_2"] = "a silent reign",
	["game.equipment_flavour.fouruniquehelmetstrint3.text_3"] = "two sightless eyes",
	["game.equipment_flavour.fouruniquehelmetstrint3.text_4"] = "feed on your pain.",
	["game.equipment_flavour.fouruniquehelmetstrint4.text_1"] = "The seeds of greatness are planted in darkness,",
	["game.equipment_flavour.fouruniquehelmetstrint4.text_2"] = "Watered by suffering,",
	["game.equipment_flavour.fouruniquehelmetstrint4.text_3"] = "Tended by desperation,",
	["game.equipment_flavour.fouruniquehelmetstrint4.text_4"] = "And bloom steel flowers of victory.",
	["game.equipment_flavour.fouruniquehelmetstrint5.text_1"] = "Pain brings clarity.",
	["game.equipment_flavour.fouruniquehelmetstrint6.text_1"] = "Death crawls in darkness, closer than we think.",
	["game.equipment_flavour.fouruniquehelmetstrint9.text_1"] = "\"Your covetous hands bring the Unlight",
	["game.equipment_flavour.fouruniquehelmetstrint9.text_2"] = "ever closer to consuming your realm.\"",
	["game.equipment_flavour.fouruniquejewel1.text_1"] = "A wellspring of vitality bubbling from within.",
	["game.equipment_flavour.fouruniquejewel10.text_1"] = "After the fires, in the depths of the Winter of the World, all life in the Vastiri banded together. Whether serpent, hyena, human, or golem, hated enemies clasped hand to claw, built refuge, and fought side by side against the Abyssals. Thus, the Third Pact was born.",
	["game.equipment_flavour.fouruniquejewel11.text_1"] = "They believed themselves driven by necessity,",
	["game.equipment_flavour.fouruniquejewel11.text_2"] = "but that desperation made them monstrous.",
	["game.equipment_flavour.fouruniquejewel12.text_1"] = "Countless souls scream in agonising harmony,",
	["game.equipment_flavour.fouruniquejewel12.text_2"] = "forever sinking under the weight of the newly dead.",
	["game.equipment_flavour.fouruniquejewel13.text_1"] = "\"Never mind the pain, it's only... making room. Unrelated fact,",
	["game.equipment_flavour.fouruniquejewel13.text_2"] = "a person can live a normal life with just one kidney. Or just one",
	["game.equipment_flavour.fouruniquejewel13.text_3"] = "lung. You never know what Vaal technology will cost you...\"",
	["game.equipment_flavour.fouruniquejewel14.text_1"] = "\"Try on another life. See how it fits. You'll",
	["game.equipment_flavour.fouruniquejewel14.text_2"] = "find that your one life is utterly inadequate.\"",
	["game.equipment_flavour.fouruniquejewel14.text_3"] = "- He of Many Names and Many Faces",
	["game.equipment_flavour.fouruniquejewel15.text_1"] = "Only a madman would ignore a god's instructions.",
	["game.equipment_flavour.fouruniquejewel2.text_1"] = "An indomitable force of control.",
	["game.equipment_flavour.fouruniquejewel3.text_1"] = "Skin like steel tempered by bright flames.",
	["game.equipment_flavour.fouruniquejewel4.text_1"] = "If you're going to act like you're better",
	["game.equipment_flavour.fouruniquejewel4.text_2"] = "than everyone else, make sure you are.",
	["game.equipment_flavour.fouruniquejewel5.text_1"] = "They believed themselves courageous and selfless,",
	["game.equipment_flavour.fouruniquejewel5.text_2"] = "but that bravery became the doom at their door.",
	["game.equipment_flavour.fouruniquejewel6.text_1"] = "They clawed their way up from the agonising depths of nonexistence,",
	["game.equipment_flavour.fouruniquejewel6.text_2"] = "breathing deep with joy the exquisite light of meaning.",
	["game.equipment_flavour.fouruniquejewel7.text_1"] = "Our world was dying, but we chose to survive.",
	["game.equipment_flavour.fouruniquejewel7.text_2"] = "We broke free from the chains within.",
	["game.equipment_flavour.fouruniquejewel8.text_1"] = "Entropy can be reversed.",
	["game.equipment_flavour.fouruniquejewel9.text_1"] = "At their height, the Vaal glittered under the sun.",
	["game.equipment_flavour.fouruniquejewel9.text_2"] = "A decade, a century, an aeon of prosperity...",
	["game.equipment_flavour.fouruniquejewel9.text_3"] = "now nothing more than a passing wonder.",
	["game.equipment_flavour.fouruniquelifeflask1.text_1"] = "\"Tukohama may be asleep, but he still gives us his strength. A small",
	["game.equipment_flavour.fouruniquelifeflask1.text_2"] = "needle, an offering, and a vial... drink deeply, my son, and you",
	["game.equipment_flavour.fouruniquelifeflask1.text_3"] = "will more than survive the coming battle... you will thrive.\"",
	["game.equipment_flavour.fouruniquelifeflask2.text_1"] = "\"Calculations complete, and He is assembled.",
	["game.equipment_flavour.fouruniquelifeflask2.text_2"] = "Our immaculate tactics are set in motion.\"",
	["game.equipment_flavour.fouruniquemanaflask1.text_1"] = "\"How do I cope with what I witnessed on Wraeclast?",
	["game.equipment_flavour.fouruniquemanaflask1.text_2"] = "Thank the Ancestors! My cup, it overflows.\"",
	["game.equipment_flavour.fouruniquemanaflask1.text_3"] = "- Lavianga, former advisor to Kaom",
	["game.equipment_flavour.fouruniquemanaflask2.text_1"] = "Uhtred drank. Verisium burned through his veins.",
	["game.equipment_flavour.fouruniquemanaflask2.text_2"] = "He gazed at death's face. With all his strength,",
	["game.equipment_flavour.fouruniquemanaflask2.text_3"] = "he turned instead to the stars, and witnessed Truth.",
	["game.equipment_flavour.fouruniqueonehandmace1.text_1"] = "The mark of the smith was widely known.",
	["game.equipment_flavour.fouruniqueonehandmace13.text_1"] = "Look the storm in the eye and you will have its respect.",
	["game.equipment_flavour.fouruniqueonehandmace14.text_1"] = "\"You mortals are insidious. You repress your",
	["game.equipment_flavour.fouruniqueonehandmace14.text_2"] = "evil, or deny it exists. Liars! When I open",
	["game.equipment_flavour.fouruniqueonehandmace14.text_3"] = "your heads, that violence floods out.\"",
	["game.equipment_flavour.fouruniqueonehandmace14.text_4"] = "- The Raven Trickster",
	["game.equipment_flavour.fouruniqueonehandmace15.text_1"] = "A common soldier from a common family kept hammering into the night",
	["game.equipment_flavour.fouruniqueonehandmace15.text_2"] = "after each grueling march, his eyes afire with starlight and determination.",
	["game.equipment_flavour.fouruniqueonehandmace15.text_3"] = "Few suspected that he would one day become the greatest among them.",
	["game.equipment_flavour.fouruniqueonehandmace2.text_1"] = "Shaped metal never forgets the forge.",
	["game.equipment_flavour.fouruniqueonehandmace3.text_1"] = "A merciful murderer swept through the streets of Sarn",
	["game.equipment_flavour.fouruniqueonehandmace3.text_2"] = "Robbing breath from the weak and worthless.",
	["game.equipment_flavour.fouruniqueonehandmace4.text_1"] = "Ezomyte loyalty was not given to distant leaders.",
	["game.equipment_flavour.fouruniqueonehandmace4.text_2"] = "It was earned by comrades in arms.",
	["game.equipment_flavour.fouruniqueonehandmace5.text_1"] = "The Abyssals were created, not born,",
	["game.equipment_flavour.fouruniqueonehandmace5.text_2"] = "and every moment in the light was agony.",
	["game.equipment_flavour.fouruniqueonehandmace6.text_1"] = "Within lies a window.",
	["game.equipment_flavour.fouruniqueonehandmace7.text_1"] = "They hoped that, trapped in its prison,",
	["game.equipment_flavour.fouruniqueonehandmace7.text_2"] = "the creature would age and perish.",
	["game.equipment_flavour.fouruniqueonehandmace7.text_3"] = "But time would not touch the fiend.",
	["game.equipment_flavour.fouruniqueonehandmace9.text_1"] = "\"A sprinkle of liquid encouragement is often",
	["game.equipment_flavour.fouruniqueonehandmace9.text_2"] = "required to garnish the perfect confession.\"",
	["game.equipment_flavour.fouruniqueonehandmace9.text_3"] = "- Brutus, Warden of Axiom",
	["game.equipment_flavour.fouruniquepinnacle1.text_1"] = "The Unblinking Eye did not cower and wail.",
	["game.equipment_flavour.fouruniquepinnacle1.text_2"] = "They stood against the end.",
	["game.equipment_flavour.fouruniquepinnacle2.text_1"] = "One warrior alone survived to face the Arbiter.",
	["game.equipment_flavour.fouruniquepinnacle3.text_1"] = "The greatest warrior of his era fought with honour.",
	["game.equipment_flavour.fouruniquepinnacle4.text_1"] = "His enemy was for endurance forged. His own waned.",
	["game.equipment_flavour.fouruniquepinnacle5.text_1"] = "Fire destroys, but fire also purifies.",
	["game.equipment_flavour.fouruniquepinnacle5.text_2"] = "Life always springs anew.",
	["game.equipment_flavour.fouruniquequarterstaff1.text_1"] = "Touch not the thorn, for only blood and pain await.",
	["game.equipment_flavour.fouruniquequarterstaff14.text_1"] = "Dannig saw Seren in his mind's eye, a public ornament of",
	["game.equipment_flavour.fouruniquequarterstaff14.text_2"] = "extravagance. Until she bore Cadigan a son and vanished.",
	["game.equipment_flavour.fouruniquequarterstaff14.text_3"] = "Decadence covering brutality, like all Kalguuran customs.",
	["game.equipment_flavour.fouruniquequarterstaff2.text_1"] = "Forged to rule the waves and tide",
	["game.equipment_flavour.fouruniquequarterstaff2.text_2"] = "Destined to serve the monkey's paw",
	["game.equipment_flavour.fouruniquequarterstaff2.text_3"] = "Strong as a tower of iron",
	["game.equipment_flavour.fouruniquequarterstaff2.text_4"] = "Deft as the needle doubt",
	["game.equipment_flavour.fouruniquequarterstaff3.text_1"] = "The night Draven attacked,",
	["game.equipment_flavour.fouruniquequarterstaff3.text_2"] = "Erian was asleep at his post.",
	["game.equipment_flavour.fouruniquequarterstaff5.text_1"] = "In our tales, and in our hearts, the rivers still flow.",
	["game.equipment_flavour.fouruniquequarterstaff6.text_1"] = "The first witch hunter knew one critical tactic:",
	["game.equipment_flavour.fouruniquequarterstaff6.text_2"] = "never let your enemy have a clear moment.",
	["game.equipment_flavour.fouruniquequiver1.text_1"] = "Mist of breath",
	["game.equipment_flavour.fouruniquequiver1.text_2"] = "Icing to lips and throat",
	["game.equipment_flavour.fouruniquequiver1.text_3"] = "As the warm ones choke and fall",
	["game.equipment_flavour.fouruniquequiver1.text_4"] = "Upon the frozen wasteland.",
	["game.equipment_flavour.fouruniquequiver12.text_1"] = "\"Why waste such a fine arrow on just one man?\"",
	["game.equipment_flavour.fouruniquequiver12.text_2"] = "- Kiravi, Vaal Archer",
	["game.equipment_flavour.fouruniquequiver2.text_1"] = "Molten feathers, veiled spark,",
	["game.equipment_flavour.fouruniquequiver2.text_2"] = "Hissing arrows from the dark.",
	["game.equipment_flavour.fouruniquequiver3.text_1"] = "Life and death ooze from the same sap.",
	["game.equipment_flavour.fouruniquequiver5.text_1"] = "\"It's a rare man that has eyes in the back of his head.\"",
	["game.equipment_flavour.fouruniquequiver5.text_2"] = "- Kiravi, Vaal Archer",
	["game.equipment_flavour.fouruniquequiver6.text_1"] = "\"Boiling frogs isn't for spells, dear. That's a disgusting",
	["game.equipment_flavour.fouruniquequiver6.text_2"] = "rumour. They're actually for brewing poisons.\"",
	["game.equipment_flavour.fouruniquequiver6.text_3"] = "- Selassie of the Black Fen",
	["game.equipment_flavour.fouruniquequiver8.text_1"] = "\"One can never fully eliminate Chance, but with the right",
	["game.equipment_flavour.fouruniquequiver8.text_2"] = "machinations, all the outcomes may be turned in your favour...\"",
	["game.equipment_flavour.fouruniquequiver8.text_3"] = "- Cadiro Perandus",
	["game.equipment_flavour.fouruniquering1.text_1"] = "If evil must always exist, so be it.",
	["game.equipment_flavour.fouruniquering1.text_2"] = "Embrace it. Become its master.",
	["game.equipment_flavour.fouruniquering10.text_1"] = "I rule the north",
	["game.equipment_flavour.fouruniquering10.text_2"] = "A legacy earned",
	["game.equipment_flavour.fouruniquering10.text_3"] = "Time and time again",
	["game.equipment_flavour.fouruniquering10.text_4"] = "Sing Meginord's song!",
	["game.equipment_flavour.fouruniquering11.text_1"] = "Doryani stumbled into a realm of madness",
	["game.equipment_flavour.fouruniquering11.text_2"] = "And awoke its Master.",
	["game.equipment_flavour.fouruniquering12.text_1"] = "Forged by the last remaining brother",
	["game.equipment_flavour.fouruniquering12.text_2"] = "to return all that was once given.",
	["game.equipment_flavour.fouruniquering13.text_1"] = "Highgate held other secrets.",
	["game.equipment_flavour.fouruniquering14.text_1"] = "It coils deeper and deeper",
	["game.equipment_flavour.fouruniquering14.text_2"] = "It slithers between thoughts",
	["game.equipment_flavour.fouruniquering14.text_3"] = "It lies beneath the valley",
	["game.equipment_flavour.fouruniquering14.text_4"] = "It lies in our minds",
	["game.equipment_flavour.fouruniquering15.text_1"] = "Forged by three brothers",
	["game.equipment_flavour.fouruniquering15.text_2"] = "so that they may recognize each other",
	["game.equipment_flavour.fouruniquering15.text_3"] = "across any distance of time or travel.",
	["game.equipment_flavour.fouruniquering16.text_1"] = "Ming slew Tranquillity",
	["game.equipment_flavour.fouruniquering16.text_2"] = "Took Chaos for his wife",
	["game.equipment_flavour.fouruniquering16.text_3"] = "And on Her immortal finger",
	["game.equipment_flavour.fouruniquering16.text_4"] = "He placed his Heart",
	["game.equipment_flavour.fouruniquering17.text_1"] = "Beyond the veil of death, there burns a fire",
	["game.equipment_flavour.fouruniquering17.text_2"] = "by whose light night is borne.",
	["game.equipment_flavour.fouruniquering18.text_1"] = "Innocence rose to godhood not on inspired faith,",
	["game.equipment_flavour.fouruniquering18.text_2"] = "but on the vilification and hatred of another.",
	["game.equipment_flavour.fouruniquering19.text_1"] = "The warriors of the Unblinking Eye moved",
	["game.equipment_flavour.fouruniquering19.text_2"] = "together as one, shoulder to shoulder.",
	["game.equipment_flavour.fouruniquering20.text_1"] = "To truly appreciate life you must be there when it ends",
	["game.equipment_flavour.fouruniquering21.text_1"] = "The ring I stole,",
	["game.equipment_flavour.fouruniquering21.text_2"] = "My finger they took,",
	["game.equipment_flavour.fouruniquering21.text_3"] = "A shrouded mind,",
	["game.equipment_flavour.fouruniquering21.text_4"] = "Cut their curses short,",
	["game.equipment_flavour.fouruniquering21.text_5"] = "As I drained their spirit",
	["game.equipment_flavour.fouruniquering21.text_6"] = "And stole their soul.",
	["game.equipment_flavour.fouruniquering21.text_7"] = "A blessing is often a curse.",
	["game.equipment_flavour.fouruniquering22.text_1"] = "Power comes to those who seek",
	["game.equipment_flavour.fouruniquering22.text_2"] = "Death comes to those who reach",
	["game.equipment_flavour.fouruniquering23.text_1"] = "When the axe finally fell, Seryl shared his pain,",
	["game.equipment_flavour.fouruniquering23.text_2"] = "and the last thought that flickered through his",
	["game.equipment_flavour.fouruniquering23.text_3"] = "fading mind was her broken, shattered scream.",
	["game.equipment_flavour.fouruniquering24.text_1"] = "They wrap around you until your blood turns as cold as theirs.",
	["game.equipment_flavour.fouruniquering25.text_1"] = "God blesses those who bless themselves.",
	["game.equipment_flavour.fouruniquering26a.text_1"] = "\"Berek hid from Storm's lightning wrath",
	["game.equipment_flavour.fouruniquering26a.text_2"] = "In the embrace of oblivious Frost",
	["game.equipment_flavour.fouruniquering26a.text_3"] = "Repelled by ice, blinded by blizzards",
	["game.equipment_flavour.fouruniquering26a.text_4"] = "Storm raged in vain",
	["game.equipment_flavour.fouruniquering26a.text_5"] = "While Berek slept.\"",
	["game.equipment_flavour.fouruniquering26a.text_6"] = "- Berek and the Untamed",
	["game.equipment_flavour.fouruniquering26b.text_1"] = "\"From Frost's ice-bound pass",
	["game.equipment_flavour.fouruniquering26b.text_2"] = "Berek taunted and jeered",
	["game.equipment_flavour.fouruniquering26b.text_3"] = "Until furious Flame scaled the mountain",
	["game.equipment_flavour.fouruniquering26b.text_4"] = "Berek escaped through the thaw",
	["game.equipment_flavour.fouruniquering26b.text_5"] = "And Frost's tortured moans.\"",
	["game.equipment_flavour.fouruniquering26b.text_6"] = "- Berek and the Untamed",
	["game.equipment_flavour.fouruniquering26c.text_1"] = "\"With Flame licking at his heels",
	["game.equipment_flavour.fouruniquering26c.text_2"] = "Berek berated the clouds",
	["game.equipment_flavour.fouruniquering26c.text_3"] = "Until vengeful Storm spewed forth his rains",
	["game.equipment_flavour.fouruniquering26c.text_4"] = "And Berek held on tight",
	["game.equipment_flavour.fouruniquering26c.text_5"] = "As Fire screamed and steamed",
	["game.equipment_flavour.fouruniquering26c.text_6"] = "And fled.\"",
	["game.equipment_flavour.fouruniquering26c.text_7"] = "- Berek and the Untamed",
	["game.equipment_flavour.fouruniquering27.text_1"] = "\"Moon after moon did Berek make fools",
	["game.equipment_flavour.fouruniquering27.text_2"] = "Of the great and Untamed Three",
	["game.equipment_flavour.fouruniquering27.text_3"] = "Until malice for a Brother",
	["game.equipment_flavour.fouruniquering27.text_4"] = "Slew the hatred of the Other",
	["game.equipment_flavour.fouruniquering27.text_5"] = "And Berek did hunt",
	["game.equipment_flavour.fouruniquering27.text_6"] = "Alone and free.\"",
	["game.equipment_flavour.fouruniquering27.text_7"] = "- Berek and the Untamed",
	["game.equipment_flavour.fouruniquering28.text_1"] = "A pact with Prospero always comes at a price.",
	["game.equipment_flavour.fouruniquering29.text_1"] = "Danger is the price of wealth.",
	["game.equipment_flavour.fouruniquering2a.text_1"] = "Those members of the Brotherhood who employ the venom of",
	["game.equipment_flavour.fouruniquering2a.text_2"] = "Trarthan ice snakes must take great care with the volatile substance.",
	["game.equipment_flavour.fouruniquering2b.text_1"] = "There is a way to survive the bite of an ice snake,",
	["game.equipment_flavour.fouruniquering2b.text_2"] = "but few have the resolve to attempt it.",
	["game.equipment_flavour.fouruniquering3.text_1"] = "Agony brings clarity to those of pure mind.",
	["game.equipment_flavour.fouruniquering30.text_1"] = "In a blaze of glory,",
	["game.equipment_flavour.fouruniquering30.text_2"] = "An anomaly defying all odds",
	["game.equipment_flavour.fouruniquering30.text_3"] = "The \"unkillable\" beast met the divine",
	["game.equipment_flavour.fouruniquering30.text_4"] = "And Ventor met his latest trophy.",
	["game.equipment_flavour.fouruniquering32.text_1"] = "Power is a matter of perspective.",
	["game.equipment_flavour.fouruniquering33.text_1"] = "Drink deeply of the Well.",
	["game.equipment_flavour.fouruniquering33.text_2"] = "Let the Abyss coil within.",
	["game.equipment_flavour.fouruniquering34.text_1"] = "The tribe revelled wildly, unaware that each fruit",
	["game.equipment_flavour.fouruniquering34.text_2"] = "they ate further bound their continuity to the fog's.",
	["game.equipment_flavour.fouruniquering34.text_3"] = "In time, the merest touch could break their reality.",
	["game.equipment_flavour.fouruniquering4.text_1"] = "As their eyes adjusted, they became aware of a strange",
	["game.equipment_flavour.fouruniquering4.text_2"] = "blue light. Countless glowing worms crawled above,",
	["game.equipment_flavour.fouruniquering4.text_3"] = "blissfully unaware of their flight from the sirens.",
	["game.equipment_flavour.fouruniquering5.text_1"] = "Where her mouth should have been there was only a whirling, black void.",
	["game.equipment_flavour.fouruniquering6.text_1"] = "The dawn of a new era is set into motion",
	["game.equipment_flavour.fouruniquering7.text_1"] = "Fear the fire that spreads like a plague.",
	["game.equipment_flavour.fouruniquering8.text_1"] = "\"The Brotherhood of Silence does not set out to torture our targets.",
	["game.equipment_flavour.fouruniquering8.text_2"] = "Excruciating pain is simply a byproduct of certain... necessary methods.\"",
	["game.equipment_flavour.fouruniqueritual1.text_1"] = "Nothingness is loathe to relinquish its grip.",
	["game.equipment_flavour.fouruniqueritual1.text_2"] = "Every moment is a struggle to exist.",
	["game.equipment_flavour.fouruniqueritual2.text_1"] = "They crawl and chitter and swarm",
	["game.equipment_flavour.fouruniqueritual2.text_2"] = "in the shadow of his presence.",
	["game.equipment_flavour.fouruniqueritual3.text_1"] = "Experiments with geomancy taught",
	["game.equipment_flavour.fouruniqueritual3.text_2"] = "the Maji more than they ever expected.",
	["game.equipment_flavour.fouruniqueritual4.text_1"] = "In an endless war against darkness,",
	["game.equipment_flavour.fouruniqueritual4.text_2"] = "one must be ever vigilant.",
	["game.equipment_flavour.fouruniquesanctum1.text_1"] = "The final element the tale-women",
	["game.equipment_flavour.fouruniquesanctum1.text_2"] = "mastered was Time itself.",
	["game.equipment_flavour.fouruniquesanctum2.text_1"] = "A fell wind brings death.",
	["game.equipment_flavour.fouruniquesanctum3.text_1"] = "\"We survived the endless winter.",
	["game.equipment_flavour.fouruniquesanctum3.text_2"] = "We endure the long summer.",
	["game.equipment_flavour.fouruniquesanctum3.text_3"] = "One day, spring will return the rains.\"",
	["game.equipment_flavour.fouruniquesanctum4a.text_1"] = "The Vaal protected those who integrated into their",
	["game.equipment_flavour.fouruniquesanctum4a.text_2"] = "culture. Many neighbours became one. Sekhema Safrin",
	["game.equipment_flavour.fouruniquesanctum4a.text_3"] = "vowed the Maraketh identity would remain resolute.",
	["game.equipment_flavour.fouruniquesanctum4b.text_1"] = "During the Winter of the World, her akhara began",
	["game.equipment_flavour.fouruniquesanctum4b.text_2"] = "shepherding jingakh across the harsh Vastiri. Sekhema",
	["game.equipment_flavour.fouruniquesanctum4b.text_3"] = "Eshtera planted the seeds of Maraketh diplomacy.",
	["game.equipment_flavour.fouruniquesanctum4c.text_1"] = "The relative peace under the fledgling Empire saw",
	["game.equipment_flavour.fouruniquesanctum4c.text_2"] = "the first Sekhema to choose, in her resplendent age and",
	["game.equipment_flavour.fouruniquesanctum4c.text_3"] = "wisdom, to step down. The role of Zaitema was born.",
	["game.equipment_flavour.fouruniquesceptre1.text_1"] = "Rare is the Necromancer who leads",
	["game.equipment_flavour.fouruniquesceptre1.text_2"] = "his undead armies from the front.",
	["game.equipment_flavour.fouruniquesceptre14.text_1"] = "Darkness howls through ancient bones, a wistful cry",
	["game.equipment_flavour.fouruniquesceptre14.text_2"] = "on hollow winds. The moon listens. The pack gathers.",
	["game.equipment_flavour.fouruniquesceptre4.text_1"] = "Tale-women may not fight directly,",
	["game.equipment_flavour.fouruniquesceptre4.text_2"] = "for they have a much higher purpose.",
	["game.equipment_flavour.fouruniquesceptre6.text_1"] = "\"When the Third Pact was written in stone, the Dreamer gave the alliance of men and",
	["game.equipment_flavour.fouruniquesceptre6.text_2"] = "beasts knowledge. In return, they gave him a drop of blood; one from each of the",
	["game.equipment_flavour.fouruniquesceptre6.text_3"] = "races of Wraeclast. In the centuries that followed, his Will began to subtly change.\"",
	["game.equipment_flavour.fouruniquesceptre6.text_4"] = "- Book of the Benevolent Dreamer, Histories {value_1}:{value_2}",
	["game.equipment_flavour.fouruniquesceptre6a.text_1"] = "\"Power of the Red Pyre! Flaming Heart of the Hive!",
	["game.equipment_flavour.fouruniquesceptre6a.text_2"] = "I release your burning message to rest here, forevermore.\"",
	["game.equipment_flavour.fouruniquesceptre6a.text_3"] = "The Dreamer declared, casting out the lingering dark embers within him.",
	["game.equipment_flavour.fouruniquesceptre6b.text_1"] = "\"With piercing eyes, you saw through the Stillness.",
	["game.equipment_flavour.fouruniquesceptre6b.text_2"] = "Undulating as one, you gloriously covered all in white.",
	["game.equipment_flavour.fouruniquesceptre6b.text_3"] = "But... I can bear you no longer.\"",
	["game.equipment_flavour.fouruniquesceptre6b.text_4"] = "The Dreamer whispered with fogging breath, ice creeping down his hand.",
	["game.equipment_flavour.fouruniquesceptre6c.text_1"] = "\"Deep in thought, you would tremble the very air before you.",
	["game.equipment_flavour.fouruniquesceptre6c.text_2"] = "Wreathed in light, you nurtured them all.",
	["game.equipment_flavour.fouruniquesceptre6c.text_3"] = "And yet... Your nature became you.\"",
	["game.equipment_flavour.fouruniquesceptre6c.text_4"] = "The Dreamer mused with aching heart, as remnants of forking tendrils burst forth.",
	["game.equipment_flavour.fouruniquesceptre6d.text_1"] = "\"We sometimes fail. We sometimes succeed. Who determines one from the other?",
	["game.equipment_flavour.fouruniquesceptre6d.text_2"] = "I now know we can never be made One, if we are bore of differing desires.",
	["game.equipment_flavour.fouruniquesceptre6d.text_3"] = "And yet, I have hope for a new truth. And I will see it... made real.\"",
	["game.equipment_flavour.fouruniquesceptre6d.text_4"] = "- The Benevolent Dreamer",
	["game.equipment_flavour.fouruniqueshielddex1.text_1"] = "\"A thief in the night, Draven did creep,",
	["game.equipment_flavour.fouruniqueshielddex1.text_2"] = "families asleep, taken, held on high.",
	["game.equipment_flavour.fouruniqueshielddex1.text_3"] = "Clever, he thought, 'til his children paid.",
	["game.equipment_flavour.fouruniqueshielddex1.text_4"] = "Nay, villain, a man never bleeds alone.\"",
	["game.equipment_flavour.fouruniqueshielddex11.text_1"] = "\"There is nowhere my vengeance cannot find you.\"",
	["game.equipment_flavour.fouruniqueshielddex12.text_1"] = "\"Lundara held back the hordes, while Solerai rose to split the sky.",
	["game.equipment_flavour.fouruniqueshielddex12.text_2"] = "With a single stroke, she ended the Winter of the World.\"",
	["game.equipment_flavour.fouruniqueshielddex12.text_3"] = "- Wranga, tale-woman of the Wahida akhara",
	["game.equipment_flavour.fouruniqueshielddex2.text_1"] = "Light and shadow chase eternal,",
	["game.equipment_flavour.fouruniqueshielddex2.text_2"] = "but neither knows the other exists...",
	["game.equipment_flavour.fouruniqueshielddex3.text_1"] = "\"Resist for long enough, and your oppressor",
	["game.equipment_flavour.fouruniqueshielddex3.text_2"] = "will lose his will. Then, you've won.\"",
	["game.equipment_flavour.fouruniqueshielddex4.text_1"] = "A window onto a realm of red,",
	["game.equipment_flavour.fouruniqueshielddex4.text_2"] = "where countless voices scream...",
	["game.equipment_flavour.fouruniqueshielddex5.text_1"] = "Cold, miserable and alone... but alive.",
	["game.equipment_flavour.fouruniqueshielddex6.text_1"] = "As a boy, in the arena, Daresso learned to",
	["game.equipment_flavour.fouruniqueshielddex6.text_2"] = "feign weakness to open up a lethal blow.",
	["game.equipment_flavour.fouruniqueshieldstr1.text_1"] = "Praetor Draven knew his only chance to subjugate",
	["game.equipment_flavour.fouruniqueshieldstr1.text_2"] = "the Ezomytes was to catch them unaware.",
	["game.equipment_flavour.fouruniqueshieldstr13.text_1"] = "Fire dances with those who doubt",
	["game.equipment_flavour.fouruniqueshieldstr13.text_2"] = "Licks the skin and flesh from the fearful",
	["game.equipment_flavour.fouruniqueshieldstr13.text_3"] = "Where there is no fear",
	["game.equipment_flavour.fouruniqueshieldstr13.text_4"] = "There is no flame",
	["game.equipment_flavour.fouruniqueshieldstr14.text_1"] = "\"Upon plains of endless chill,",
	["game.equipment_flavour.fouruniqueshieldstr14.text_2"] = "They Who Never Tire... dominate.",
	["game.equipment_flavour.fouruniqueshieldstr14.text_3"] = "They Who Never Surrender... terrify.",
	["game.equipment_flavour.fouruniqueshieldstr14.text_4"] = "And They Who Lay Beneath... wait for Nightfall.\"",
	["game.equipment_flavour.fouruniqueshieldstr14.text_5"] = "- Tul, She That Silences",
	["game.equipment_flavour.fouruniqueshieldstr2.text_1"] = "The Counts of Ogham share a",
	["game.equipment_flavour.fouruniqueshieldstr2.text_2"] = "legacy of cunning and power.",
	["game.equipment_flavour.fouruniqueshieldstr3.text_1"] = "Welcome to Wraeclast.",
	["game.equipment_flavour.fouruniqueshieldstr4.text_1"] = "\"Beyond fire, blood, and nightmare,",
	["game.equipment_flavour.fouruniqueshieldstr4.text_2"] = "the Saviour will build Utopia.\"",
	["game.equipment_flavour.fouruniqueshieldstr5.text_1"] = "Some stories are never told.",
	["game.equipment_flavour.fouruniqueshieldstr6.text_1"] = "A true predator does not chase; It waits.",
	["game.equipment_flavour.fouruniqueshieldstr7.text_1"] = "Blood shed is blood shared.",
	["game.equipment_flavour.fouruniqueshieldstr8.text_1"] = "Our hearts cry out",
	["game.equipment_flavour.fouruniqueshieldstr8.text_2"] = "but are silenced by our flesh",
	["game.equipment_flavour.fouruniqueshieldstr8.text_3"] = "and so we give up our flesh.",
	["game.equipment_flavour.fouruniqueshieldstrdex1.text_1"] = "The unending carnage of war",
	["game.equipment_flavour.fouruniqueshieldstrdex1.text_2"] = "mercilessly grinds away",
	["game.equipment_flavour.fouruniqueshieldstrdex1.text_3"] = "at body and mind.",
	["game.equipment_flavour.fouruniqueshieldstrdex12.text_1"] = "From aeons past, Dannig felt the Runefather's",
	["game.equipment_flavour.fouruniqueshieldstrdex12.text_2"] = "gaze, challenging him. There is no honour in ease.",
	["game.equipment_flavour.fouruniqueshieldstrdex12.text_3"] = "True greatness is torn from the jaws of defeat.",
	["game.equipment_flavour.fouruniqueshieldstrdex2.text_1"] = "Lead by example, and you shall never be alone.",
	["game.equipment_flavour.fouruniqueshieldstrdex4.text_1"] = "Ride the western wind, and take flight.",
	["game.equipment_flavour.fouruniqueshieldstrint1.text_1"] = "May your resolve never waver.",
	["game.equipment_flavour.fouruniqueshieldstrint2.text_1"] = "The druids swore to protect the Grelwood with their very lives.",
	["game.equipment_flavour.fouruniqueshieldstrint3.text_1"] = "A swift mind solves problems before they occur.",
	["game.equipment_flavour.fouruniqueshieldstrint4.text_1"] = "When the Red Sekhema called,",
	["game.equipment_flavour.fouruniqueshieldstrint4.text_2"] = "the Ardura were the first to answer.",
	["game.equipment_flavour.fouruniqueshieldstrint5.text_1"] = "When blood is paid, the weak think twice.",
	["game.equipment_flavour.fouruniqueshieldstrint6.text_1"] = "My bearer shall be guarded by flame,",
	["game.equipment_flavour.fouruniqueshieldstrint6.text_2"] = "for I am the phoenix, forever radiant in glory.",
	["game.equipment_flavour.fouruniquespear1.text_1"] = "The Baleful Gem's corruption lingers still...",
	["game.equipment_flavour.fouruniquespear13.text_1"] = "The spear was specially forged to assassinate Voll,",
	["game.equipment_flavour.fouruniquespear13.text_2"] = "but Maligaro never got a chance to use it...",
	["game.equipment_flavour.fouruniquespear14.text_1"] = "\"My people? I'm not doing this for them.",
	["game.equipment_flavour.fouruniquespear14.text_2"] = "They belong to me. They want this for me.",
	["game.equipment_flavour.fouruniquespear14.text_3"] = "Their sacrifice is a gift they give out of love",
	["game.equipment_flavour.fouruniquespear14.text_4"] = "and adoration... I deserve it. I am their Queen.\"",
	["game.equipment_flavour.fouruniquespear15.text_1"] = "May the Lightless drown in the violence of His devotion.",
	["game.equipment_flavour.fouruniquespear2.text_1"] = "The might of the Eternal Empire was formidable,",
	["game.equipment_flavour.fouruniquespear2.text_2"] = "but rebels of every culture stood together as one.",
	["game.equipment_flavour.fouruniquespear3.text_1"] = "The Sacred Hunt ends with mercy.",
	["game.equipment_flavour.fouruniquespear4.text_1"] = "Heads fall to the sand, just as the star fell from the sky",
	["game.equipment_flavour.fouruniquespear5.text_1"] = "\"You killed their Golden Sekhema. The Maraketh will think of nothing",
	["game.equipment_flavour.fouruniquespear5.text_2"] = "but vengeance now.\" - Dimos, Advisor to General Titucius",
	["game.equipment_flavour.fouruniquespear6.text_1"] = "\"In the hands of Orbala, it made a god bleed.\"",
	["game.equipment_flavour.fouruniquespear6.text_2"] = "- Wranga, tale-woman of the Wahida akhara",
	["game.equipment_flavour.fouruniquespear7.text_1"] = "Born in a star of man's own make,",
	["game.equipment_flavour.fouruniquespear7.text_2"] = "fused to her hand by her last mistake.",
	["game.equipment_flavour.fouruniquespirit1.text_1"] = "To become a warrior and a hunter, each young",
	["game.equipment_flavour.fouruniquespirit1.text_2"] = "Azmeri must prove themselves before the Spirit.",
	["game.equipment_flavour.fouruniquestaff1.text_1"] = "The candlemass tradition was born in a time of darkness and fear.",
	["game.equipment_flavour.fouruniquestaff13.text_1"] = "In ghastly pits beneath the world,",
	["game.equipment_flavour.fouruniquestaff13.text_2"] = "Kulemak grows countless new bodies,",
	["game.equipment_flavour.fouruniquestaff13.text_3"] = "each more powerful than the last.",
	["game.equipment_flavour.fouruniquestaff13.text_4"] = "Not all of his abominations survive.",
	["game.equipment_flavour.fouruniquestaff14.text_1"] = "\"From what beast you derived, we can only fathom.",
	["game.equipment_flavour.fouruniquestaff14.text_2"] = "Aye, you of living ice, rotting gill, and untold nightmare!",
	["game.equipment_flavour.fouruniquestaff14.text_3"] = "We Brinerot return ye to the sea.\"",
	["game.equipment_flavour.fouruniquestaff14.text_4"] = "- Weylam Roth",
	["game.equipment_flavour.fouruniquestaff17.text_1"] = "Bow before her... or suffer the most gruelling death imaginable.",
	["game.equipment_flavour.fouruniquestaff18.text_1"] = "\"Where the boy went, ravens gathered,",
	["game.equipment_flavour.fouruniquestaff18.text_2"] = "feasting on misery. His vile influence",
	["game.equipment_flavour.fouruniquestaff18.text_3"] = "spread, swift as the carnage they wrought.\"",
	["game.equipment_flavour.fouruniquestaff2.text_1"] = "Shed by the winged beast of night,",
	["game.equipment_flavour.fouruniquestaff2.text_2"] = "A scaly frost-encrusted thorn.",
	["game.equipment_flavour.fouruniquestaff2.text_3"] = "All who feel its wintry light",
	["game.equipment_flavour.fouruniquestaff2.text_4"] = "Shiver in pain at the frozen dawn.",
	["game.equipment_flavour.fouruniquestaff3.text_1"] = "An ancient Azmeri staff, overgrown by roots...",
	["game.equipment_flavour.fouruniquestaff5.text_1"] = "Burn to cinders, scar and maim,",
	["game.equipment_flavour.fouruniquestaff5.text_2"] = "Rule a world, bathed in flame.",
	["game.equipment_flavour.fouruniquestaff6.text_1"] = "That which was broken may yet break.",
	["game.equipment_flavour.fouruniquetalisman1.text_1"] = "A sensitive few among the first settlers of Ezomyr",
	["game.equipment_flavour.fouruniquetalisman1.text_2"] = "followed the wisps by canoe. On a misty forested",
	["game.equipment_flavour.fouruniquetalisman1.text_3"] = "island, Cirel of Tarth stood waiting to greet them.",
	["game.equipment_flavour.fouruniquetalisman10.text_1"] = "\"A traditional hatungo does not carry an axe,",
	["game.equipment_flavour.fouruniquetalisman10.text_2"] = "it is true. But as Narumoa showed us, there",
	["game.equipment_flavour.fouruniquetalisman10.text_3"] = "are many ways to crush one's enemy...\"",
	["game.equipment_flavour.fouruniquetalisman14.text_1"] = "Gruthkul was the Mother of Despair...",
	["game.equipment_flavour.fouruniquetalisman14.text_2"] = "but one day, the Father will return,",
	["game.equipment_flavour.fouruniquetalisman14.text_3"] = "and discover the fate of his children.",
	["game.equipment_flavour.fouruniquetalisman2.text_1"] = "If you see the blushing tree of the northern woods,",
	["game.equipment_flavour.fouruniquetalisman2.text_2"] = "remember: \"Blossoms of red, the tree's been fed.",
	["game.equipment_flavour.fouruniquetalisman2.text_3"] = "Blossoms of white, prepare for a fight.\"",
	["game.equipment_flavour.fouruniquetalisman4.text_1"] = "In a time of great need, surrounded by Abyssals,",
	["game.equipment_flavour.fouruniquetalisman4.text_2"] = "the Wayward Druid came to the Sun Clan's aid.",
	["game.equipment_flavour.fouruniquetalisman4.text_3"] = "It is a debt they have never forgotten.",
	["game.equipment_flavour.fouruniquetalisman8.text_1"] = "Long ago, the witches of the Azak Tribe learned",
	["game.equipment_flavour.fouruniquetalisman8.text_2"] = "how to tap into the flow of Vivid lifeforce to",
	["game.equipment_flavour.fouruniquetalisman8.text_3"] = "'cooperate' with their enemies... forcefully.",
	["game.equipment_flavour.fouruniquetwohandmace1.text_1"] = "There was a very clear and delicious",
	["game.equipment_flavour.fouruniquetwohandmace1.text_2"] = "reason why the Ezomytes chose to",
	["game.equipment_flavour.fouruniquetwohandmace1.text_3"] = "stop their flight and settle in Phaaryl.",
	["game.equipment_flavour.fouruniquetwohandmace10.text_1"] = "\"Drunken Erqi boasted to Tukohama; the God of War",
	["game.equipment_flavour.fouruniquetwohandmace10.text_2"] = "challenged him to a clash of strength. Woe to the",
	["game.equipment_flavour.fouruniquetwohandmace10.text_3"] = "Divine - he should have made it a test of skill!\"",
	["game.equipment_flavour.fouruniquetwohandmace13.text_1"] = "The secret Order endured by publicly",
	["game.equipment_flavour.fouruniquetwohandmace13.text_2"] = "praying however the Templars demanded.",
	["game.equipment_flavour.fouruniquetwohandmace13.text_3"] = "One day, justice would fall upon them...",
	["game.equipment_flavour.fouruniquetwohandmace14.text_1"] = "Infinite mutations over endless eons borne upon it in a singular moment.",
	["game.equipment_flavour.fouruniquetwohandmace2.text_1"] = "\"The crack of bone, the spray of blood.",
	["game.equipment_flavour.fouruniquetwohandmace2.text_2"] = "Is there sweeter music?\"",
	["game.equipment_flavour.fouruniquetwohandmace2.text_3"] = "- Hrimnor of the Ezomytes.",
	["game.equipment_flavour.fouruniquetwohandmace3.text_1"] = "The art of surgery advances one mistake at a time.",
	["game.equipment_flavour.fouruniquetwohandmace4.text_1"] = "The mind may have no limits, but the skull sure does.",
	["game.equipment_flavour.fouruniquetwohandmace5.text_1"] = "Secrecy and silence are powers all their own.",
	["game.equipment_flavour.fouruniquetwohandmace6.text_1"] = "Be not deceived by the treachery of men.",
	["game.equipment_flavour.fouruniquetwohandmace7.text_1"] = "The faithful may continue to serve, even after death.",
	["game.equipment_flavour.fouruniquetwohandmace8.text_1"] = "\"The finest prosperity grows from the direst",
	["game.equipment_flavour.fouruniquetwohandmace8.text_2"] = "carnage. Such is the nature of progress.\"",
	["game.equipment_flavour.fouruniquetwohandmace8.text_3"] = "- Doryani of the Vaal",
	["game.equipment_flavour.fouruniquetwohandmace9.text_1"] = "The sea strikes the rock relentlessly.",
	["game.equipment_flavour.fouruniquetwohandmace9.text_2"] = "Whether in one day or in ten thousand years,",
	["game.equipment_flavour.fouruniquetwohandmace9.text_3"] = "eventually the rock will crumble,",
	["game.equipment_flavour.fouruniquetwohandmace9.text_4"] = "and the Brine King's domain will grow.",
	["game.equipment_flavour.fouruniqueultimatum1.text_1"] = "Man retains sanity and strives toward civilisation",
	["game.equipment_flavour.fouruniqueultimatum1.text_2"] = "only under the blessed veil of ignorance.",
	["game.equipment_flavour.fouruniqueultimatum2.text_1"] = "The most horrifying ideas often begin with a simple innovation.",
	["game.equipment_flavour.fouruniqueultimatum3.text_1"] = "The Banished Architect sought to employ the darkest secrets of the Vaal.",
	["game.equipment_flavour.fouruniqueultimatum4.text_1"] = "The first Karui born on the fringes of the Vaal empire developed a blood fever born of corruption.",
	["game.equipment_flavour.fouruniquewand1.text_1"] = "With a flick of the finger, their fates are written,",
	["game.equipment_flavour.fouruniquewand1.text_2"] = "the pages torn to a million pieces.",
	["game.equipment_flavour.fouruniquewand15.text_1"] = "In that moment, Viridi's bones became",
	["game.equipment_flavour.fouruniquewand15.text_2"] = "branches, weaving over the Darkness.",
	["game.equipment_flavour.fouruniquewand15.text_3"] = "She coiled around the nothing,",
	["game.equipment_flavour.fouruniquewand15.text_4"] = "trapping it within her everything.",
	["game.equipment_flavour.fouruniquewand16.text_1"] = "Smithed from ancient metal",
	["game.equipment_flavour.fouruniquewand16.text_2"] = "wrought from the very stars.",
	["game.equipment_flavour.fouruniquewand16.text_3"] = "It is a means to call upon them,",
	["game.equipment_flavour.fouruniquewand16.text_4"] = "for one capable of wielding it.",
	["game.equipment_flavour.fouruniquewand2.text_1"] = "One way or another, it will find what it seeks.",
	["game.equipment_flavour.fouruniquewand3.text_1"] = "From the smallest seeds",
	["game.equipment_flavour.fouruniquewand3.text_2"] = "To the tallest redwoods,",
	["game.equipment_flavour.fouruniquewand3.text_3"] = "Life endures in Wraeclast.",
	["game.equipment_flavour.fouruniquewand4.text_1"] = "Adonia rose with eyes afire, emanating a ghastly aura, and",
	["game.equipment_flavour.fouruniquewand4.text_2"] = "broke off a carving from the wall of the Throne Room.",
	["game.equipment_flavour.fouruniquewand4.text_3"] = "\"You think me powerless without my wand? Insult me again!\"",
	["game.equipment_flavour.fouruniquewand5.text_1"] = "He alone was welcome in the sacred spaces of the Titans.",
	["game.equipment_flavour.fouruniquewand7.text_1"] = "Lost in the Black Fen, Erian hoped that dawn would save him.",
	["game.equipment_flavour.fouruniquewand7.text_2"] = "He had no idea how far away the light truly was.",
	["game.equipment_flavour.vaallimbreplacements.text_1"] = "\"Behold! A marvel of innovation! Pay no mind the cost of flesh...\"",
	["game.equipment_flavour.vaallimbreplacements.text_2"] = "- Guatelitzi, Architect of Flesh",
